"use strict";(self.webpackChunkfrontend_v4=self.webpackChunkfrontend_v4||[]).push([[333],{6333(e){e.exports=JSON.parse('{"schemaVersion":"mgq-story-graph/v1","compiledAt":"2026-08-21T11:04:29.895Z","nodes":{"P00":{"id":"P00","title":"女神之梦","status":"compiled","scenes":[{"kind":"narration","speaker":"旁白","text":"……这里是哪里？"},{"kind":"narration","speaker":"旁白","text":"周围飘溢着柔和的光线，满是庄严的气氛。"},{"kind":"narration","speaker":"旁白","text":"这，难道是梦境吗？"},{"kind":"dialogue","speaker":"？？？","text":"鲁卡…… 勇者鲁卡……"},{"kind":"narration","speaker":"旁白","text":"……不知从何处传来了声音，我似乎听到有人在呼唤着我的名字。"},{"kind":"narration","speaker":"旁白","text":"这声音既平稳，又充满了慈爱。"},{"kind":"narration","speaker":"旁白","text":"在我面前出现的是——"},{"kind":"narration","speaker":"旁白","text":"天啊，是创世之女神伊莉娅丝大人的身姿！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"勇者鲁卡哟……听到了我的声音吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"听到了，伊莉娅丝大人——！"},{"kind":"narration","speaker":"旁白","text":"听到了伊莉娅丝大人的声音，我兴奋得全身发抖。"},{"kind":"narration","speaker":"旁白","text":"创造了这个世界，并深深地爱着全人类的创世女神。"},{"kind":"narration","speaker":"旁白","text":"并且，慈爱地守护着所有冒险者的女神。"},{"kind":"narration","speaker":"旁白","text":"在这样伟大的存在面前，深深地崇拜着她的我，无法压抑内心的激动——"},{"kind":"narration","speaker":"旁白","text":"即使，这仅仅是一个美好的梦。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"……貌似没有听见我的话呢……"},{"kind":"narration","speaker":"旁白","text":"是的，就是那么回事。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"……再敢油嘴滑舌的话，就等着制裁降临吧。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"你知道该怎么办了吧？"},{"kind":"narration","speaker":"旁白","text":"强烈的闪电贯穿了我的身体，全身受到了像是燃烧殆尽一般的冲击。"},{"kind":"narration","speaker":"旁白","text":"然后，我渐渐失去了意识——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"……至今，几十亿年前。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"那是你们人类根本没法用时间来衡量的遥远的太古……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"我创造了这个世界。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"首先是大地、然后是天空、海洋、植物、动物、鸟类、昆虫……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"最后，创造出了你们「人类」。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"但是——即使是我，也不是全知全能的。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"在创造人类的过程中，也做出了很多失败的作品。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"那就是，魔物—— 丑陋，而且禁忌的存在。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"魔物，是邪恶的象征。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"有时使用暴力，有时使用淫乱的手段折磨着你们人类。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"我深深地爱着弱小的人类。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"对于折磨着人类的禁忌的存在—— 魔物，深深地憎恨着。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"话说鲁卡……你也终于成长到可以开始「冒险旅行的年龄」了呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"是的……从我小时候开始，就一直期待着这一天！"},{"kind":"narration","speaker":"旁白","text":"「冒险旅行的年龄」是指，可以接受伊莉娅丝大人的洗礼的年龄。"},{"kind":"narration","speaker":"旁白","text":"接受了洗礼以后，就能被承认是一名勇者了。"},{"kind":"narration","speaker":"旁白","text":"目标成为一位勇者的我，一直期待着「冒险旅行的年龄」到来的那一天。"},{"kind":"narration","speaker":"旁白","text":"为了那天的到来，一直以来我在和平的村子里，努力地修行着剑技——"},{"kind":"narration","speaker":"旁白","text":"终于！"},{"kind":"narration","speaker":"旁白","text":"到达「冒险旅行的年龄」的那一天，就是明天了！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"至今为止，我已经为许许多多少年进行了洗礼。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"把对勇者的祝福和女神的守护，给予了很多年轻的战士。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"但是——他们至今没有任何人能做到，消灭现在的魔王。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"像五百年前，成功消灭当时魔王的勇者——海因里希一样的年轻人，至今仍未出现。"},{"kind":"narration","speaker":"旁白","text":"勇者海因里希——"},{"kind":"narration","speaker":"旁白","text":"五百年前，战胜并消灭了当时极尽残暴无道的魔王的那位传说中的勇者。"},{"kind":"narration","speaker":"旁白","text":"他的剑技可以劈开大地，令强大的邪恶屈服，将正义贯彻到最后——"},{"kind":"narration","speaker":"旁白","text":"不愧是，勇者中的勇者。"},{"kind":"narration","speaker":"旁白","text":"对以成为真正的勇者为目标的我来说，对他的崇拜已经无法用言语表达。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"但是，鲁卡——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"你，也许也能够成为将魔王打倒的勇者。"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？ 我，我也能……？"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"勇敢地出发吧，鲁卡。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"我，无论何时都会关注着并守护着你——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"沐浴在柔和的阳光中，我迎来了新的一天的清晨。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"刚才看到的景象，难道仅仅是梦境吗——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"――不，那绝对不可能是单纯的一个梦！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"伊莉娅丝大人一定是通过梦的形式，向我传达了重要的信息！"},{"kind":"dialogue","speaker":"鲁卡","text":"伊莉娅丝大人，真诚地感激您的指引。"},{"kind":"dialogue","speaker":"鲁卡","text":"请务必，守护这个尚不成熟的我吧——"},{"kind":"narration","speaker":"旁白","text":"和一直以来一样，起床以后的晨祷。"},{"kind":"narration","speaker":"旁白","text":"然后，对着从来不离身的遗物戒指低声说道——"},{"kind":"dialogue","speaker":"鲁卡","text":"早上好，妈妈。"},{"kind":"dialogue","speaker":"鲁卡","text":"今天，我终于要以勇者的身份去旅行了……"},{"kind":"narration","speaker":"旁白","text":"接着站起身，我开始了一天的准备工作。"},{"kind":"narration","speaker":"旁白","text":"天气相当晴朗，比平日的清晨更加清爽。"},{"kind":"narration","speaker":"旁白","text":"今天上午我将要前往伊莉娅丝神殿，接受成为勇者的洗礼。"},{"kind":"narration","speaker":"旁白","text":"然后，就可以开始退治魔王的旅途了。"},{"kind":"narration","speaker":"旁白","text":"这个家，不知是否还能回来——"},{"kind":"narration","speaker":"旁白","text":"想到这点，我不经感慨万千。"},{"kind":"dialogue","speaker":"鲁卡","text":"……在没有完成魔王退治之前，应该不会回到这里了吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"剩下可以做的事情，就是把屋子打扫得干干净净。"},{"kind":"narration","speaker":"旁白","text":"吃完早饭以后，我开始开开心心地打扫屋子。"},{"kind":"narration","speaker":"旁白","text":"常言道，好聚好散，好去好来。"},{"kind":"narration","speaker":"旁白","text":"也就是说，就算要出发旅行了，只要还在家就应该把家打扫干净―/"},{"kind":"dialogue","speaker":"村民","text":"不、不、不好了！"},{"kind":"dialogue","speaker":"鲁卡","text":"……哎？怎么了？"},{"kind":"narration","speaker":"旁白","text":"刚刚整理好床铺，就听到外面有男子的叫喊声。"},{"kind":"narration","speaker":"旁白","text":"发生什么事了吗，听声音好象是樵夫汉斯先生。"},{"kind":"narration","speaker":"旁白","text":"大清早的，发生了什么事啊——"},{"kind":"dialogue","speaker":"村民","text":"附近的森林，出现了魔物！"},{"kind":"dialogue","speaker":"鲁卡","text":"什……什么！？"},{"kind":"narration","speaker":"旁白","text":"在这个和平的伊丽姬丝维鲁村附近，居然出现了魔物！？"},{"kind":"narration","speaker":"旁白","text":"伊丽姬丝维鲁村虽然只是个小村子，但这里有世界有名的大神殿啊。"},{"kind":"narration","speaker":"旁白","text":"侍奉伊莉娅丝大人的神殿，伊莉娅丝神殿。"},{"kind":"narration","speaker":"旁白","text":"被那样伟大的神力守护，魔物本应该无法靠近的啊——"},{"kind":"dialogue","speaker":"村民","text":"大家，都躲到家里去！魔物说不定会进村的！"},{"kind":"dialogue","speaker":"大婶","text":"啊，啊哇哇哇哇……！"},{"kind":"dialogue","speaker":"小孩子","text":"妈，妈妈呀！！"},{"kind":"narration","speaker":"旁白","text":"和平的村子，瞬间陷入了恐慌之中。"},{"kind":"narration","speaker":"旁白","text":"在这个终于可以开始冒险旅行的日子，村子居然被魔物袭击了——"},{"kind":"dialogue","speaker":"鲁卡","text":"怎，怎么办！？"},{"kind":"narration","speaker":"旁白","text":"实际上，别说与魔物战斗了，我就连真正的魔物长什么样都不知道。"},{"kind":"narration","speaker":"旁白","text":"但是，我可是今后要踏上退治魔王旅途的人。"},{"kind":"narration","speaker":"旁白","text":"如果连村庄附近的魔物都吓得不敢面对的话，作为勇者是不合格的！"}],"choices":[{"text":"继续","next":"P01"}],"battles":["ilias-dream-lesson"],"next":"P01"},"P01":{"id":"P01","title":"洗礼之日","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"好的，要上了！"},{"kind":"narration","speaker":"旁白","text":"我手持宝剑，飞奔出了家门。"},{"kind":"narration","speaker":"旁白","text":"生我养我的村子，要用我的手自己来守护！"},{"kind":"dialogue","speaker":"鲁卡","text":"还是算了吧……"},{"kind":"narration","speaker":"旁白","text":"我纠结地动摇中，就在这个时候——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"鲁卡……拿起你的剑。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"用你的手，守护这个村子……"},{"kind":"dialogue","speaker":"鲁卡","text":"刚，刚才那是什么……？"},{"kind":"narration","speaker":"旁白","text":"一瞬间，眼前所出现了幻象。"},{"kind":"narration","speaker":"旁白","text":"刚才，那是女神伊莉娅丝大人的指引吗？"},{"kind":"narration","speaker":"旁白","text":"是否要听从伊莉娅丝大人的指引，前往退治魔物呢……？"},{"kind":"dialogue","speaker":"鲁卡","text":"既然是伊莉娅丝大人的指引，那就只能照办了……"},{"kind":"narration","speaker":"旁白","text":"我手持宝剑，飞奔出了家门。"},{"kind":"narration","speaker":"旁白","text":"生我养我的村子，要用我的手自己来守护——"},{"kind":"narration","speaker":"旁白","text":"既然伊莉娅丝大人这样要求了，我当然必须做到。"},{"kind":"dialogue","speaker":"鲁卡","text":"还是算了吧……"},{"kind":"narration","speaker":"旁白","text":"就这样，我还是放弃了。"},{"kind":"narration","speaker":"旁白","text":"接着，耳边传来了不可思议的声音。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"和我期待的不一样呢，鲁卡。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"你没有成为勇者的资格。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"接受神的制裁吧……"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？"},{"kind":"narration","speaker":"旁白","text":"强烈的闪电贯穿了我的身体，全身受到了像是燃烧殆尽一般的冲击。"},{"kind":"narration","speaker":"旁白","text":"然后，我渐渐失去了意识——"}],"choices":[{"text":"继续","next":null}],"battles":[],"next":"P02"},"P02":{"id":"P02","title":"村外启程","status":"compiled","scenes":[{"kind":"dialogue","speaker":"农夫","text":"咦呀，快逃啊……！"},{"kind":"dialogue","speaker":"青年","text":"呀……！这、这还是头一次……！"},{"kind":"narration","speaker":"旁白","text":"整个村子陷入了大混乱中。"},{"kind":"narration","speaker":"旁白","text":"早晨在外耕种的人们，飞快地逃进了自己家中。"},{"kind":"narration","speaker":"旁白","text":"我逆着人潮而行，向村子的入口飞奔而去。"},{"kind":"narration","speaker":"旁白","text":"邻家的大婶看见我后，对着我高声大喊。"},{"kind":"dialogue","speaker":"贝蒂大婶","text":"别过去，鲁卡！"},{"kind":"dialogue","speaker":"贝蒂大婶","text":"这里，就交给伊莉娅丝神殿的士兵们吧！"},{"kind":"dialogue","speaker":"鲁卡","text":"没关系，贝蒂大婶！我可是一位勇者呢！"},{"kind":"dialogue","speaker":"贝蒂大婶","text":"勇者？你……还没有经过洗礼吧！？"},{"kind":"dialogue","speaker":"贝蒂大婶","text":"喂，别过去啊！"},{"kind":"narration","speaker":"旁白","text":"的确，只有经过洗礼，才能成为真正的勇者——"},{"kind":"narration","speaker":"旁白","text":"就算如此，我怎么会输给杂鱼魔物呢！"},{"kind":"narration","speaker":"旁白","text":"不理会贝蒂大婶的阻止，我沿着村中的大路奔跑。"},{"kind":"narration","speaker":"旁白","text":"然后，飞奔出了村子！"},{"kind":"narration","speaker":"旁白","text":"继续沿着大路，我跑进了森林里面。"},{"kind":"narration","speaker":"旁白","text":"我停下了脚步，打量着四周。"},{"kind":"dialogue","speaker":"鲁卡","text":"哈啊，哈啊……魔物，到底在哪里啊？"},{"kind":"narration","speaker":"旁白","text":"在安静的森林中，我环视着四周。"},{"kind":"narration","speaker":"旁白","text":"进入森林的路途中，并没有看到敌人——"},{"kind":"narration","speaker":"旁白","text":"正当我这么想着的时候。"},{"kind":"narration","speaker":"旁白","text":"忽然，森林的小道上，出现了一只魔物的身影！"},{"kind":"dialogue","speaker":"史莱姆娘","text":"啊哈哈，美味的男孩子～☆"},{"kind":"narration","speaker":"旁白","text":"史莱姆娘对着有点发呆的我噗哧噗哧地笑着。"},{"kind":"narration","speaker":"旁白","text":"那粘体状的身体，一摇一晃地扭动着——"},{"kind":"dialogue","speaker":"鲁卡","text":"这，这就是……魔物……"},{"kind":"narration","speaker":"旁白","text":"虽然已经举起剑摆好了架势，但当我看清她的模样时却愣住了。"},{"kind":"narration","speaker":"旁白","text":"亲眼看到魔物，这还是第一次。"},{"kind":"narration","speaker":"旁白","text":"没有想象中的压迫力，反而有点可爱……但是，异样。"},{"kind":"narration","speaker":"旁白","text":"咕噜咕噜地起伏波动的身体，和人类相差甚远。"},{"kind":"narration","speaker":"旁白","text":"以这样的人外娘作为对手，我真的可以打败她么——"},{"kind":"narration","speaker":"旁白","text":"之前满满的自信在转瞬之间就消失了。"},{"kind":"dialogue","speaker":"史莱姆娘","text":"啊啦啦……？"},{"kind":"dialogue","speaker":"史莱姆娘","text":"难道说，你是第一次看到魔物吗～？"},{"kind":"narration","speaker":"旁白","text":"的确如此，不过我并没有作出回应。"},{"kind":"narration","speaker":"旁白","text":"我可绝对不愿意，露出什么胆小害怕的样子。"},{"kind":"narration","speaker":"旁白","text":"握着剑柄的手震动着，带动手上的剑也开始颤动。"},{"kind":"narration","speaker":"旁白","text":"我双手用力握住我的剑，压制住了剑的颤动，并装作很镇静的样子。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个…… 这里，离人类居住的村子已经很近了。"},{"kind":"dialogue","speaker":"鲁卡","text":"所以，可以请你老实地回去吗？"},{"kind":"narration","speaker":"旁白","text":"稳定住手中的剑后，我提心吊胆地对史莱姆娘问道。"},{"kind":"narration","speaker":"旁白","text":"绝对，不用害怕……大概吧。"},{"kind":"narration","speaker":"旁白","text":"即使是魔物，也应该不喜欢无谓的战斗吧。"},{"kind":"narration","speaker":"旁白","text":"好好地交谈的话，她也应该能明白的吧——"},{"kind":"dialogue","speaker":"鲁卡","text":"村子里的大家，都感到很害怕。"},{"kind":"dialogue","speaker":"鲁卡","text":"如果，你没有恶意的话——"},{"kind":"dialogue","speaker":"史莱姆娘","text":"啊哈哈……你这家伙，难道是和平主义者？"},{"kind":"dialogue","speaker":"史莱姆娘","text":"那样的请求我是不会听的哟～，因为我现在肚子饿了嘛。"},{"kind":"dialogue","speaker":"史莱姆娘","text":"还是说…… 你想用自己的精液来满足我呢？"},{"kind":"dialogue","speaker":"鲁卡","text":"那、那种事…… 我办不到……"},{"kind":"narration","speaker":"旁白","text":"很多魔物，都以人类的精液作为食物。"},{"kind":"narration","speaker":"旁白","text":"可是对人类来说，给予魔物精液是一大禁忌。"},{"kind":"narration","speaker":"旁白","text":"和魔物交合，射精——"},{"kind":"narration","speaker":"旁白","text":"可是会触犯女神伊莉娅丝的五大戒律之一，魔奸的戒律。"},{"kind":"dialogue","speaker":"鲁卡","text":"……伊莉娅丝大人的五大戒律，规定了不许与魔物性交。"},{"kind":"dialogue","speaker":"鲁卡","text":"所以说，把精液给你是不行的呢……"},{"kind":"dialogue","speaker":"史莱姆娘","text":"那么……我就要强行把精液榨出来了呢～"},{"kind":"dialogue","speaker":"鲁卡","text":"咕……！"},{"kind":"narration","speaker":"旁白","text":"果然，这场战斗已经无可避免。"},{"kind":"narration","speaker":"旁白","text":"就在我举起剑做好架势的时候—— /"},{"kind":"narration","speaker":"旁白","text":"突然，在眼前展开了另外的景象。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"勇者鲁卡哟…… 我正在你的心中与你交谈。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"就让我把战斗的方法传授给你吧。"}],"choices":[{"text":"继续","next":null}],"battles":[],"next":"P03"},"P03":{"id":"P03","title":"史莱姆娘遭遇","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"拜、拜托您了……！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"那么……我将战斗的方法传授给你。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"左下方显示的绿色条，表示的是你的ＨＰ。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"只是为了方便起见，我们才把它称为血条……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"实际上，它是体力、气力、精神力、抵抗力、生命力之类的综合表现。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"说那是斗志的体现，大概是最确切的了。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"如果，你在战斗中受到了伤害——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"实际演示一下吧。会稍微有点痛呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"呜啊啊啊！！"},{"kind":"narration","speaker":"旁白","text":"强烈的闪电贯穿了我的身体，全身受到了像是燃烧殆尽一般的冲击。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"明白了吗？"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"根据受到的伤害程度，你的血条会减少。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"正如刚才所说，这个血条表示的是生命力和精神力的总和。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"无论是受到肉体的攻击，还是精神上的冲击，都会使血条减少。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"总而言之……如果受到了攻击，ＨＰ就会相应地减少。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"然后，当ＨＰ减少到０的时候——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"就表示你失去了对魔物的斗志。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"如果变成那样，无论是继续战斗还是逃跑都是做不到的。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"魔物会将你凌辱，或者是玩弄——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"无论被魔物做了什么，都完全无法反抗。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"绝对，不要让那样的事情发生哦。知道了吗？"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"然后在右侧显示的同样的长条，那是敌方的ＨＰ。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"当这个血条降到０的时候，就代表魔物被打倒了。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"关于ＨＰ的解说，都听明白了吗？"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"那么接下来，是关于回合制战斗的说明。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"所谓的回合制战斗，就是你的回合、敌人的回合、你的回合、敌人的回合……这样，不断由双方轮流行动的战斗形式。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"每当轮到你的回合时，屏幕上会显示出你的指令窗口。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"本来显示指令窗口的地方应该是在我们对话的窗口这里，不过……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"那样就无法显示我说的话了，所以这回就让指令窗口显示在上面了。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"那么，来详细地看看内容吧。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"首先是「攻击」。正如字面上的意思。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"使用剑对敌人进行攻击。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"「技能」是…… 现在，你还没有掌握任何技能。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"当你能使用技能了之后，再来说明这部分吧。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"在说明「挣脱」之前，需要知道魔物们可以使用一些拘束你行动的技能。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"例如用触手捆着你，或者是紧紧地抱着你——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"封锁你的行动之后，然后持续地给予你伤害。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"如果你在被拘束的状态下使用「攻击」，在绝大多数情况下都无法给予对手伤害。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"虽然也有例外……不过那个就先不用管了。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"然后为了解开那样的拘束，就需要使用「挣脱」指令。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"如果被拘束了，马上使用「挣脱」。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"这是战斗的基本知识，绝对不要忘了哟。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"根据敌人的不同，在某些情况下或许不需要使用「挣脱」。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"而且，有些强力的魔物会使用绝对无法挣脱的技能，请小心。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"「防御」是，在这一回合内全力地防守。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"受到的伤害会降低为原来的一半或更低，但是代价是你也无法行动。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"而且请记住，被拘束的时候是无法使用「防御」指令的。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"「不行动」是……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"在这一回合里，无抵抗地承受敌人的攻击。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"当然，这在战术上没有任何意义。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"只是徒然地受到敌人的攻击，损失自己的ＨＰ。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"对于真正的勇者来说，这样的选项是没有必要的。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"「投降」是……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"无抵抗地向敌人投降，这是绝对禁止的行为。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"选择这个的话，你就无法做出任何行动了。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"在ＨＰ耗尽之前，单方面地被对方玩弄。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"这样的指令，真正的勇者是绝对不会选择的。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"然后是最后一个指令，关于「恳求」。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"这个指令与「投降」相同，在ＨＰ耗尽之前都会一直被对方戏弄。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"但是，这时候的敌人会使用你指定的技能。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"希望对手用特定的技能使出最后一击的话，就可以使用这个指令。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"另外在「恳求」里可以选择的技能，必须是你曾经见过的技能。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"从来没有见过的技能，颜色会变暗以表示无法选择。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"……嘛，那种事情没有记住的必要。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"如果是真正的勇者，不可能死乞白赖地去恳求魔物。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"更不用说，被魔物任意玩弄之类的……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"鲁卡，我相信你哟。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"我能教给你的就是以上这些。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"都听明白了吗？"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"需要我再说明一次吗？"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"我知道了……那么我再一次，将战斗的方法传授给你。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"左下方显示的绿色条，表示的是你的ＨＰ。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"只是为了方便起见，我们才把它称为血条……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"实际上，它是体力、气力、精神力、抵抗力、生命力之类的综合表现。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"说那是斗志的体现，大概是最确切的了。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"如果，你在战斗中受到了伤害——"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"实际演示一下吧。会稍微有点痛呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……！？在这个状态下——"},{"kind":"narration","speaker":"旁白","text":"强烈的闪电贯穿了我的身体，全身受到了像是燃烧殆尽一般的冲击。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"啊……！"},{"kind":"narration","speaker":"旁白","text":"然后，我渐渐失去了意识——"},{"kind":"dialogue","speaker":"鲁卡","text":"我明白了！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"另外，在战斗中不能逃跑。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"勇者选择逃跑什么的，那是不可能的。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"另外，你——"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……！？"},{"kind":"narration","speaker":"旁白","text":"怎么，突然中断了？"},{"kind":"narration","speaker":"旁白","text":"伊莉娅丝大人，刚才没说完的是什么……？"},{"kind":"dialogue","speaker":"史莱姆娘","text":"怎么了？你怎么呆住了……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，不是……"},{"kind":"narration","speaker":"旁白","text":"我返回了现实，和史莱姆娘对峙的状态。"},{"kind":"narration","speaker":"旁白","text":"战斗的方式我已经明白了，没有必要再犹豫了。"},{"kind":"narration","speaker":"旁白","text":"好，要上了！"},{"kind":"dialogue","speaker":"鲁卡","text":"我已经迫不及待准备战斗了！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"是吗……有这份勇气实在是很好。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"不过，不要忘记这一点。"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"你，一直——"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……！？"},{"kind":"narration","speaker":"旁白","text":"怎么，突然中断了？"},{"kind":"narration","speaker":"旁白","text":"伊莉娅丝大人，刚才没说完的是什么？"},{"kind":"dialogue","speaker":"史莱姆娘","text":"怎么了？ 你怎么呆住了……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，不是……"},{"kind":"narration","speaker":"旁白","text":"我返回了现实，和史莱姆娘对峙的状态。"},{"kind":"narration","speaker":"旁白","text":"战斗的方式我已经明白了，没有必要再犹豫了。"},{"kind":"narration","speaker":"旁白","text":"好，要上了——！"}],"choices":[{"text":"继续","next":null}],"battles":["slime-girl-first-encounter","goblin-girl-roadside-ambush","mini-lamia-duel"],"next":"P04"},"P04":{"id":"P04","title":"旅伴登场槽","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"哈啊、哈啊、哈啊……"},{"kind":"narration","speaker":"旁白","text":"史莱姆娘逃跑之后——"},{"kind":"narration","speaker":"旁白","text":"我松开了手中的剑，身体无力地跪在了地上。"},{"kind":"narration","speaker":"旁白","text":"无论怎么看，这都是一场无比艰难的战斗。"},{"kind":"narration","speaker":"旁白","text":"如果对方能再坚持三十秒的话，倒下的就是我了吧。"},{"kind":"narration","speaker":"旁白","text":"但不管怎么说，胜利就是胜利，这是毋庸置疑的！"},{"kind":"dialogue","speaker":"鲁卡","text":"胜、胜利了……"},{"kind":"narration","speaker":"旁白","text":"首次取得的胜利，让我激动得全身发抖。"},{"kind":"narration","speaker":"旁白","text":"虽然我作为一名战士尚未成熟，但是我依然守护了养育我的村子。"},{"kind":"dialogue","speaker":"鲁卡","text":"而且，没有杀死对手就解决了事态呢……"},{"kind":"narration","speaker":"旁白","text":"把剑收回剑鞘，我安心地松了一口气。"},{"kind":"narration","speaker":"旁白","text":"我绝对不讨厌魔物。"},{"kind":"narration","speaker":"旁白","text":"倒不如说，我一直抱着的信念是人类与魔物应该和睦共处。"},{"kind":"narration","speaker":"旁白","text":"正因为如此，我才希望成为勇者，下定决心要打倒魔王。"},{"kind":"dialogue","speaker":"鲁卡","text":"回村里去吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"今天是我开始冒险旅行的日子呢……"},{"kind":"narration","speaker":"旁白","text":"而且，今天要去接受伊莉娅丝女神的洗礼。"},{"kind":"narration","speaker":"旁白","text":"然后我将以一位勇者的身份开始退治魔王的旅行！"},{"kind":"narration","speaker":"旁白","text":"带着胜利的喜悦和对旅行的期待，我向着村子走去。"},{"kind":"dialogue","speaker":"鲁卡","text":"魔王退治，吗……"},{"kind":"narration","speaker":"旁白","text":"我停下了脚步，抬头仰望着天空。"},{"kind":"narration","speaker":"旁白","text":"在不是那么遥远的过去，人类还与魔物一同生活着。"},{"kind":"narration","speaker":"旁白","text":"一部分魔物生活在人类的城市和村庄里，并且人类也接受了她们。"},{"kind":"narration","speaker":"旁白","text":"虽然种族不同，偶尔还会爆发一点冲突——"},{"kind":"narration","speaker":"旁白","text":"即使如此，人类和魔物也没有成为彻底的对立面。"},{"kind":"narration","speaker":"旁白","text":"但是，三十年前—— 发生的一件大事彻底改变了这一切。"},{"kind":"narration","speaker":"旁白","text":"那是离魔王城最近的莱米那村里，发生的虐杀事件。"},{"kind":"narration","speaker":"旁白","text":"据说成群的魔物袭击了村庄，村子变成了人间地狱。"},{"kind":"narration","speaker":"旁白","text":"结果，莱米那村被毁灭。只留下了一片废墟。"},{"kind":"narration","speaker":"旁白","text":"连一个生还者都没有的惨剧——"},{"kind":"narration","speaker":"旁白","text":"从「莱米那虐杀」之后，人类和魔物的关系发生了巨大的变化。"},{"kind":"narration","speaker":"旁白","text":"原本与人类一起生活的大量魔物被赶出村子，而且野生的魔物开始袭击人类。"},{"kind":"narration","speaker":"旁白","text":"统率着所有魔物的魔王，对人类宣布了全面战争的开始。"},{"kind":"narration","speaker":"旁白","text":"人类和魔物的关系彻底决裂，双方相互憎恨着——"},{"kind":"narration","speaker":"旁白","text":"——虽然这么说，但是在不同的地方情况也不一样。"},{"kind":"narration","speaker":"旁白","text":"虽然大部分地方对魔物非常地抵触，但仍然有少数地方，人类依旧和魔物共同生活着。"},{"kind":"narration","speaker":"旁白","text":"有对所有魔物非常憎恨的人存在，也有认为魔物不都是那么邪恶的人存在。"},{"kind":"narration","speaker":"旁白","text":"虽然那么说，但是人类和魔物的关系总体而言变得十分险恶是不容置疑的事实。"},{"kind":"dialogue","speaker":"鲁卡","text":"所以，我要……！"},{"kind":"narration","speaker":"旁白","text":"只要把指使魔物作恶的魔王打倒，这一切一定可以回到从前那样。"},{"kind":"narration","speaker":"旁白","text":"回到以前，人类和魔物和睦共存的日子。"},{"kind":"narration","speaker":"旁白","text":"为了这个目标，我一定要打倒魔王——"},{"kind":"narration","speaker":"旁白","text":"哪怕是要牺牲我的性命作为代价也在所不惜。"},{"kind":"dialogue","speaker":"鲁卡","text":"哇哇……发生了什么事！？"},{"kind":"narration","speaker":"旁白","text":"突然，附近传来了巨大冲击的巨响声。"},{"kind":"narration","speaker":"旁白","text":"在这附近，貌似发生了什么大爆炸的事件。"},{"kind":"dialogue","speaker":"鲁卡","text":"离这里很近啊……究竟发生了什么？"},{"kind":"narration","speaker":"旁白","text":"我朝着发出声音的方向跑了过去。"},{"kind":"narration","speaker":"旁白","text":"穿过树木之间的空隙，走进森林的深处。"},{"kind":"narration","speaker":"旁白","text":"在那里的是—— /"},{"kind":"narration","speaker":"旁白","text":"一位漂亮的女性，横躺在了地面上！"},{"kind":"dialogue","speaker":"鲁卡","text":"不，那是……"},{"kind":"narration","speaker":"旁白","text":"下半身是蛇身，而且皮肤的颜色——"},{"kind":"narration","speaker":"旁白","text":"不管怎么看，都不像是人类。"},{"kind":"narration","speaker":"旁白","text":"魔物…… 而且，看起来是一只相当强大的妖魔。"},{"kind":"narration","speaker":"旁白","text":"不知道到底发生了什么，这只妖魔躺在地上一动不动。"},{"kind":"dialogue","speaker":"鲁卡","text":"这只魔物，死掉了吗……？"},{"kind":"narration","speaker":"旁白","text":"这只奇妙的魔物躺卧着，一动也不动。"},{"kind":"narration","speaker":"旁白","text":"看周围倒得七零八落的树木，凹陷的地面——"},{"kind":"narration","speaker":"旁白","text":"该不会，这只魔物是从天上掉下来的吧。"},{"kind":"narration","speaker":"旁白","text":"这到底，是什么情况……？"},{"kind":"dialogue","speaker":"鲁卡","text":"怎、怎么办啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"如果她还活着，要不要帮她呢……"},{"kind":"narration","speaker":"旁白","text":"当然，我心里对魔物并没有敌意。"},{"kind":"narration","speaker":"旁白","text":"倒不如说，我希望看到人类与魔物和睦共存的世界。"},{"kind":"narration","speaker":"旁白","text":"虽说是魔物，但也不能就这么放着不管——"},{"kind":"narration","speaker":"旁白","text":"然而现在的我，没有空闲的时间啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么办呢，快到时间了呢……"},{"kind":"narration","speaker":"旁白","text":"今天对我来说，是接受女神伊莉娅丝洗礼的特别日子。"},{"kind":"narration","speaker":"旁白","text":"接受成为勇者的洗礼的时机，只有到达「开始冒险旅行年龄」当天的正午。"},{"kind":"narration","speaker":"旁白","text":"如果不能在那时赶到伊莉娅丝神殿接受洗礼仪式的话，就不会再有第二次的机会了。"},{"kind":"narration","speaker":"旁白","text":"也就是说，这是一生只有一次的机会。"},{"kind":"narration","speaker":"旁白","text":"到正午暂时还有时间，不过——"},{"kind":"narration","speaker":"旁白","text":"如果被卷进这件事里，可能就赶不上洗礼的时间了。"},{"kind":"narration","speaker":"旁白","text":"从眼前的情况看来，事情好象非常地麻烦。"},{"kind":"narration","speaker":"旁白","text":"相比这里的情况，重要的洗礼才是排在第一位考虑的吧——"},{"kind":"dialogue","speaker":"鲁卡","text":"呜……该怎么办呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"但是，不管她又于心不忍……"},{"kind":"narration","speaker":"旁白","text":"烦恼了一会以后，我决定——"},{"kind":"dialogue","speaker":"鲁卡","text":"……就装作没看见吧……"},{"kind":"narration","speaker":"旁白","text":"今天可是一辈子才有一次的机会"},{"kind":"narration","speaker":"旁白","text":"这个机会，绝对不能错过……"},{"kind":"dialogue","speaker":"鲁卡","text":"抱歉了……肯定会有过路的好心人帮助你的。"},{"kind":"narration","speaker":"旁白","text":"内心涌上了好像将捡到的猫再度抛弃的罪恶感——"},{"kind":"narration","speaker":"旁白","text":"但是最终我还是匆匆忙忙地离开了现场。/"},{"kind":"dialogue","speaker":"鲁卡","text":"不论怎么说，见死不救的话就没资格成为一个勇者了！"},{"kind":"narration","speaker":"旁白","text":"我走到了她面前，仔细看了一下她的脸。"},{"kind":"narration","speaker":"旁白","text":"首先，确定一下是死是活吧——"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？"},{"kind":"narration","speaker":"旁白","text":"妖魔此时突然睁开了眼睛。"},{"kind":"narration","speaker":"旁白","text":"她目不转睛地盯着我，然后直立起了身体。"},{"kind":"dialogue","speaker":"妖魔","text":"……这里是？"},{"kind":"narration","speaker":"旁白","text":"盯着我的脸，魔物突然就这样开口。"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？"},{"kind":"dialogue","speaker":"妖魔","text":"……这里是哪，问你话呢？"},{"kind":"narration","speaker":"旁白","text":"感觉那妖魔很没礼貌，忽然就提出了质问。"},{"kind":"narration","speaker":"旁白","text":"面对这样的情况，我——"},{"kind":"narration","speaker":"旁白","text":"我没有做任何回答，仅仅看着那只妖魔的脸。"}],"choices":[{"text":"继续","next":null}],"battles":["bandit-two-wave-showdown"],"next":"P05"},"P05":{"id":"P05","title":"伊莉娅丝指令","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"这里是天堂，你已经死掉了。"},{"kind":"narration","speaker":"旁白","text":"我当然是在说谎话啦。"}],"choices":[{"text":"继续","next":null}],"battles":[],"next":"P06"},"P06":{"id":"P06","title":"前往伊利亚斯贝鲁克","status":"compiled","scenes":[{"kind":"narration","speaker":"旁白","text":"忽然妖魔眼里放出了异样的光芒。"},{"kind":"dialogue","speaker":"妖魔","text":"我再问你，这里是哪？"},{"kind":"dialogue","speaker":"鲁卡","text":"女王大人，这里是伊丽姬丝维鲁村附近！"},{"kind":"narration","speaker":"旁白","text":"为什么—— 我的嘴巴，不由自主地回答了问题！？"},{"kind":"narration","speaker":"旁白","text":"而且，为何是敬语？"},{"kind":"dialogue","speaker":"鲁卡","text":"呃，这里是伊丽姬丝维鲁村附近……"},{"kind":"narration","speaker":"旁白","text":"稍微有点发愣，我还是老实回答了问题。"},{"kind":"dialogue","speaker":"妖魔","text":"居然飞到这种地方了啊。那个女人，什么怪力啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"那个女人？"},{"kind":"dialogue","speaker":"妖魔","text":"……那么，你又是谁呢？"},{"kind":"narration","speaker":"旁白","text":"完全无视我的疑问，她又接连提出问题。"},{"kind":"narration","speaker":"旁白","text":"然后，我应该怎么办呢——"},{"kind":"narration","speaker":"旁白","text":"我没有回答问题。然后——"},{"kind":"narration","speaker":"旁白","text":"不经意间，妖魔的眼中放出异样的光芒……"},{"kind":"narration","speaker":"旁白","text":"妖魔的眼里再次放出异样的光芒……"},{"kind":"dialogue","speaker":"妖魔","text":"……你这家伙是什么人？"},{"kind":"dialogue","speaker":"鲁卡","text":"啊！我是卑贱的见习勇者！"},{"kind":"dialogue","speaker":"鲁卡","text":"是这附近的伊丽姬丝维鲁村出身的！"},{"kind":"narration","speaker":"旁白","text":"怎么回事……我的嘴巴不由自主地回答了。"},{"kind":"narration","speaker":"旁白","text":"怎么回事……我的嘴巴又不由自主地回答了。"},{"kind":"narration","speaker":"旁白","text":"而且还是用如此卑微的口气。"}],"choices":[{"text":"继续","next":null}],"battles":[],"next":"F01"},"X01":{"id":"X01","title":"拒绝讨伐之旅","status":"pending","scenes":[],"battles":[]},"F01":{"id":"F01","title":"伊利亚斯贝鲁克","status":"compiled","scenes":[{"kind":"narration","speaker":"旁白","text":"抛开这些不说，目的地伊莉娅丝贝鲁库离这不远了。"},{"kind":"narration","speaker":"旁白","text":"我们继续向北前进着。"},{"kind":"narration","speaker":"旁白","text":"太阳下山，我们终于到了伊莉娅丝贝鲁库附近。"},{"kind":"narration","speaker":"旁白","text":"从这里，可以看到城内大量的建筑，"},{"kind":"narration","speaker":"旁白","text":"不过，如果就这样进去肯定是不行的——"},{"kind":"narration","speaker":"旁白","text":"因为身边有这个家伙……"},{"kind":"dialogue","speaker":"鲁卡","text":"爱丽丝……你能变成人类的样子么？"},{"kind":"narration","speaker":"旁白","text":"整个伊莉娅丝大陆都是排斥魔物的，这里也不例外。"},{"kind":"narration","speaker":"旁白","text":"如果爱丽丝就这样进去了，势必引起大骚乱。"},{"kind":"dialogue","speaker":"爱丽丝","text":"变成人类的样子很简单，但是我会很不爽的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"为什么余非要伪装成人类呢——"},{"kind":"dialogue","speaker":"鲁卡","text":"你不伪装成人类怎么去吃美食呢？"},{"kind":"dialogue","speaker":"爱丽丝","text":"呜……真是令人困惑，"},{"kind":"dialogue","speaker":"爱丽丝","text":"没办法了，这样可以了吗？/"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯嗯！就这样，感觉不错。"},{"kind":"narration","speaker":"旁白","text":"话说这身不知羞耻的服装是怎么回事……"},{"kind":"narration","speaker":"旁白","text":"就这样，我们进入了伊莉娅丝贝鲁库。"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么回事？城市的样子有点奇怪啊？"},{"kind":"narration","speaker":"旁白","text":"道路两边，既没有旅行者也没有商人。"},{"kind":"narration","speaker":"旁白","text":"傍晚时分不应该没人吧……"},{"kind":"narration","speaker":"旁白","text":"似乎所有人都躲在家里不敢出来了，"},{"kind":"narration","speaker":"旁白","text":"另外整个城镇弥漫着浓浓的杀气——"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么了？到底发生什么事了？"},{"kind":"narration","speaker":"旁白","text":"顺着大路，我一路跑向中央广场——"},{"kind":"narration","speaker":"旁白","text":"忽然感到了异样的气氛，我躲到了街边的树阴后面。"},{"kind":"dialogue","speaker":"鲁卡","text":"那，那家伙是！"},{"kind":"dialogue","speaker":"龙人族的魔剑士","text":"……真是令人扫兴啊，"},{"kind":"dialogue","speaker":"龙人族的魔剑士","text":"这个地方就没有一个像样的强者吗？！"},{"kind":"narration","speaker":"旁白","text":"在空旷的广场中间，站着一位魔剑士。"},{"kind":"dialogue","speaker":"战士Ａ","text":"啊……可恶……"},{"kind":"dialogue","speaker":"战士Ｂ","text":"难以置信，太强了……"},{"kind":"dialogue","speaker":"战士Ｃ","text":"呜啊啊……"},{"kind":"narration","speaker":"旁白","text":"有三个战士在她的面前，"},{"kind":"narration","speaker":"旁白","text":"旁边还有几十个倒在地上的战士。"},{"kind":"narration","speaker":"旁白","text":"这都是那个魔剑士一个人做到的吗？"},{"kind":"dialogue","speaker":"龙人族的魔剑士","text":"还剩三人……你们，不攻过来吗？"},{"kind":"dialogue","speaker":"战士Ａ","text":"咕……！"},{"kind":"narration","speaker":"旁白","text":"三位战士，在战斗之前就已经被魔剑士的气势压倒了。"},{"kind":"narration","speaker":"旁白","text":"无论怎么看，他们都不可能赢的。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个魔剑士，难道说是……"},{"kind":"narration","speaker":"旁白","text":"巨大的剑，那副盔甲，龙人族的魔剑士——"},{"kind":"narration","speaker":"旁白","text":"没错，就连我这个乡下人都知道这家伙！"},{"kind":"narration","speaker":"旁白","text":"魔王军四天王之一，魔剑士古兰贝莉娅！"},{"kind":"narration","speaker":"旁白","text":"那精妙的剑技，无论是人类还是魔物都无人可匹敌。"},{"kind":"narration","speaker":"旁白","text":"仅仅一人就可以摧毁一座城市，一人击溃了一万人的军队啦，类似的勇猛传说层出不穷。"},{"kind":"narration","speaker":"旁白","text":"那么强大的魔剑士，竟然会袭击这乡下城镇。"},{"kind":"narration","speaker":"旁白","text":"就如我所见，她根本就是孤身一人前来的……"},{"kind":"dialogue","speaker":"鲁卡","text":"爱，爱丽丝…… 怎，怎么办……"},{"kind":"narration","speaker":"旁白","text":"回头一看—— 像往常一样，爱丽丝又消失了……"},{"kind":"narration","speaker":"旁白","text":"果然逃了吗……"},{"kind":"narration","speaker":"旁白","text":"那家伙，嘴上总说些厉害的话………"},{"kind":"narration","speaker":"旁白","text":"会不会仅仅只是说话厉害而已……"},{"kind":"narration","speaker":"旁白","text":"这里是我到达的第一个城市，怎么会出现这种级别的强敌……"},{"kind":"narration","speaker":"旁白","text":"一般条件下，不至于在第一个城市就要和ＢＯＳＳ交手吧。"},{"kind":"narration","speaker":"旁白","text":"难道说我的旅途，在这里就要结束了吗——"},{"kind":"narration","speaker":"旁白","text":"——话说，现在不是该考虑这种问题的时刻！"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"喂，你们三个，"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"这座城市马上就被我攻下了，你们就这样旁观？"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"还是说，面对敌人你们准备放弃勇者的责任了？"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"……好了，快点给我选择！"},{"kind":"dialogue","speaker":"战士Ａ","text":"可，可恶啊……！"},{"kind":"dialogue","speaker":"战士Ｂ","text":"区区魔物，不要那么嚣张啦！！！"},{"kind":"narration","speaker":"旁白","text":"三人中的两人向古兰贝莉娅冲了过去。"},{"kind":"narration","speaker":"旁白","text":"剩下的一人，因为身体害怕得发抖没法动弹。"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"那份勇气值得赞赏。"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"但是如果没有相应的实力，勇气也没有意义！！"},{"kind":"narration","speaker":"旁白","text":"古兰贝莉娅的巨剑突然被火焰包裹了起来。"},{"kind":"narration","speaker":"旁白","text":"一瞬间，灼热的烈风弥漫了周围的空间。"},{"kind":"narration","speaker":"旁白","text":"那熊熊燃烧的业火似乎要燃尽一切。"},{"kind":"dialogue","speaker":"鲁卡","text":"哇，这是……！"},{"kind":"narration","speaker":"旁白","text":"还记得，魔王军四天王分别精通火、水、风、土四个属性。"},{"kind":"narration","speaker":"旁白","text":"古兰贝莉娅得意的正是火属性。"},{"kind":"dialogue","speaker":"战士Ａ","text":"哈呀！"},{"kind":"narration","speaker":"旁白","text":"冒着热气，勇敢突入的战士！"},{"kind":"narration","speaker":"旁白","text":"但是—— /"},{"kind":"narration","speaker":"旁白","text":"变魔术一般，古兰贝莉娅的身影突然消失了。"},{"kind":"dialogue","speaker":"战士Ａ","text":"啊……！"},{"kind":"narration","speaker":"旁白","text":"下个瞬间，战士晕过去了。"},{"kind":"narration","speaker":"旁白","text":"在他背后站着的正是古兰贝莉娅。"},{"kind":"dialogue","speaker":"鲁卡","text":"刚才，发生了什么……？"},{"kind":"narration","speaker":"旁白","text":"那是，一瞬间发生的事情。"},{"kind":"narration","speaker":"旁白","text":"如同闪电般的手法，以眼睛都看不见的速度，给了战士一击。"},{"kind":"dialogue","speaker":"战士Ｂ","text":"你这个——！"},{"kind":"narration","speaker":"旁白","text":"另外一个战士上段斩从背后劈向了古兰贝莉娅。"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"太慢了……"},{"kind":"narration","speaker":"旁白","text":"古兰贝莉娅转身将刀身横着挥出——"},{"kind":"narration","speaker":"旁白","text":"战士的剑砍下，但是速度远远不及对方。"},{"kind":"dialogue","speaker":"鲁卡","text":"呜哇……！"},{"kind":"narration","speaker":"旁白","text":"剑气的压力，几乎都能击中我藏身的地方了。"},{"kind":"narration","speaker":"旁白","text":"强烈的热风，似乎都要把我周围烧焦了。——"},{"kind":"dialogue","speaker":"战士Ｂ","text":"咕哇……"},{"kind":"narration","speaker":"旁白","text":"在那么近的地方，根本就没办法回避啊。"},{"kind":"narration","speaker":"旁白","text":"战士的剑变为了碎片，人也随着热风倒下。/"},{"kind":"dialogue","speaker":"鲁卡","text":"强，太强了……"},{"kind":"narration","speaker":"旁白","text":"……好强。 压倒性的实力。"},{"kind":"narration","speaker":"旁白","text":"就算是刚才那两个战士，也都是比我还要厉害的强者。"},{"kind":"narration","speaker":"旁白","text":"即使这样，也像是小孩子一样被打败了。"},{"kind":"narration","speaker":"旁白","text":"老实说，我相当向往那份强大。"},{"kind":"dialogue","speaker":"战士Ａ","text":"啊……"},{"kind":"dialogue","speaker":"战士Ｂ","text":"呜……"},{"kind":"narration","speaker":"旁白","text":"但是，那两个战士貌似还活着……"},{"kind":"narration","speaker":"旁白","text":"周围的战士好像也都活着，"},{"kind":"narration","speaker":"旁白","text":"那样压倒性的实力，反而刀下留人是比较难做到的吧。"},{"kind":"narration","speaker":"旁白","text":"就这样，还剩下一个在瑟瑟发抖的战士……"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"那么，你打算怎么做呢？"},{"kind":"dialogue","speaker":"战士Ｃ","text":"呜，哇……！"},{"kind":"narration","speaker":"旁白","text":"他背对着古兰贝莉娅，迅速逃跑了——"},{"kind":"narration","speaker":"旁白","text":"古兰贝莉娅也没有追的意思。"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"明智的选择。"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"但是，今后不管是战士还是勇者的名誉都不复存在了。"},{"kind":"dialogue","speaker":"鲁卡","text":"糟糕了………这个情况。"},{"kind":"narration","speaker":"旁白","text":"看样子，这座城市的强者都被打败了。"},{"kind":"narration","speaker":"旁白","text":"这座城市已经没有人能守护了。"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"一个也没有了吗？"},{"kind":"dialogue","speaker":"古兰贝莉娅","text":"既然如此，就别抱怨这座城市被魔族占领了！"},{"kind":"narration","speaker":"旁白","text":"古兰贝莉娅一声大吼，震撼了整个城镇。"},{"kind":"narration","speaker":"旁白","text":"但是躲在家中的居民们，连一点声响都不敢发出。"},{"kind":"narration","speaker":"旁白","text":"这也就意味着全部屈服了……"},{"kind":"narration","speaker":"旁白","text":"我，我该怎么办？"},{"kind":"narration","speaker":"旁白","text":"显而易见，现在的我是根本没有可能打败她的。"}],"choices":[{"text":"继续","next":null}],"battles":["bandit-goblin-duel","bandit-vampire-duel"],"next":"F02"},"F02":{"id":"F02","title":"伊利亚斯港","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"喂、喂喂…… 稍微等一下……！ 哇！"},{"kind":"narration","speaker":"旁白","text":"爱丽丝一下子就把我推到在床上，并且用尾巴卷起了我。"},{"kind":"dialogue","speaker":"鲁卡","text":"不……不行啊……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"在说什么呢，这可是特训。你这家伙不知道自己对快乐攻击的耐性很弱吗？/"},{"kind":"dialogue","speaker":"爱丽丝","text":"如果无法抵抗快乐攻击，你的旅途不知道什么时候就要悲惨的落幕了呢。"},{"kind":"dialogue","speaker":"爱丽丝","text":"就算这样也没关系吗……？/"},{"kind":"dialogue","speaker":"鲁卡","text":"那样的……当然不行………"},{"kind":"dialogue","speaker":"爱丽丝","text":"所以这是特训啊。你只要忍耐余给予的刺激就好。/"},{"kind":"dialogue","speaker":"鲁卡","text":"但……但是——"},{"kind":"narration","speaker":"旁白","text":"结果我就这样被推倒了……"},{"kind":"narration","speaker":"旁白","text":"不管怎么说，我都没法拒绝。"},{"kind":"narration","speaker":"旁白","text":"抵抗不了，只能忍耐了……"},{"kind":"dialogue","speaker":"爱丽丝","text":"来吧……/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝就这样，一下子把我的裤子脱掉了。"},{"kind":"narration","speaker":"旁白","text":"被剥掉裤子的下半身，完全暴露在爱丽丝的面前。"},{"kind":"dialogue","speaker":"爱丽丝","text":"库库库……已经变得这么大了啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嘴上还说什么不要不要的，真是不坦率的家伙呢。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"看起来已经忍不住了吗……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"这回余就给你来点特别服务吧。/"},{"kind":"dialogue","speaker":"鲁卡","text":"你，其实是肚子饿了吧……"},{"kind":"narration","speaker":"旁白","text":"表面上说是要给我特训，其实你是想要我的精液吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"别啰哩啰嗦了。这是一石二鸟……不一石三鸟。"},{"kind":"dialogue","speaker":"爱丽丝","text":"完成了特训、处理了性欲，还满足了余的肚子。/"},{"kind":"dialogue","speaker":"鲁卡","text":"但是爱丽丝。但是伊莉娅丝大人的戒律，禁止任何魔物交合――"},{"kind":"dialogue","speaker":"爱丽丝","text":"啊真是的，麻烦的家伙。"},{"kind":"dialogue","speaker":"爱丽丝","text":"只要不用余的阴道让你射精就不算破戒了。/"},{"kind":"narration","speaker":"旁白","text":"就这样爱丽丝的手掌，握住了我的肉棒。"},{"kind":"narration","speaker":"旁白","text":"柔软又温暖的手掌，把我的东西包裹了起来――"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜呜……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"仅仅这样握住，肉棒就一跳一跳的……/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝一边确认着手感，微微地增加了一些握力。"},{"kind":"narration","speaker":"旁白","text":"这巧妙的刺激，给我带来了极大的快感。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么，你能坚持多久呢……"},{"kind":"dialogue","speaker":"爱丽丝","text":"就这样，让我用手把汁液榨出来吧。/"},{"kind":"narration","speaker":"旁白","text":"握住肉棒的爱丽丝的手，开始使劲上下套弄起来。"},{"kind":"narration","speaker":"旁白","text":"虽然看起来很激烈，实际上却相当温柔。"},{"kind":"narration","speaker":"旁白","text":"用手指围成了圈圈，巧妙地对阴茎施以刺激——"},{"kind":"narration","speaker":"旁白","text":"一边激烈地上下套弄，一边对敏感部分重点进攻——"},{"kind":"narration","speaker":"旁白","text":"那双富有魔力的手，给我带来了极大的快感。"},{"kind":"dialogue","speaker":"鲁卡","text":"呜、啊啊啊啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼呼……余的手技，你到底能忍耐多久呢……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"照这个样子看来，没法坚持多久呢……/"},{"kind":"narration","speaker":"旁白","text":"看着我恍惚的脸，爱丽丝很开心地笑了。"},{"kind":"narration","speaker":"旁白","text":"被那优越感满满的视线注视着，马上就要高潮了。"},{"kind":"narration","speaker":"旁白","text":"这真是，对男人来说是无法接受的屈辱——"},{"kind":"dialogue","speaker":"鲁卡","text":"住手啊，再这样的话…… 啊啊啊……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这家伙，这个地方真是弱啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"才那么一会，就发出了那么不像样的声音呢——/"},{"kind":"narration","speaker":"旁白","text":"柔软的掌心温柔地握住了我的肉棒，并施以巧妙的握力。"},{"kind":"narration","speaker":"旁白","text":"用手指围成的圈对肉棒中心重点进攻，持续的快感使得我的腰不停摇摆。"},{"kind":"narration","speaker":"旁白","text":"这样持续的刺激，要射精的感觉如开水般很快沸腾——"},{"kind":"dialogue","speaker":"鲁卡","text":"呜啊啊…… 这样的，住手啊……"},{"kind":"narration","speaker":"旁白","text":"被妖魔的手搞到射精可是极大的禁忌。"},{"kind":"narration","speaker":"旁白","text":"为了不破戒，我努力地抵抗着快感——"},{"kind":"narration","speaker":"旁白","text":"爱丽丝一边施展着她的手技，一边微笑着欣赏着我的抵抗。"},{"kind":"dialogue","speaker":"爱丽丝","text":"想想就知道的结果。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这家伙，被余用手就能轻松搞定了哦。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"真是没节操的家伙呢，呵呵呵呵……/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的脸上，浮现了能令男人疯狂的妖艳表情。"},{"kind":"narration","speaker":"旁白","text":"同时，直到刚才还空着的左手对着我的龟头发起了进攻。"},{"kind":"narration","speaker":"旁白","text":"一边涂抹着我溢出的前列腺液，一边库尼库尼地按摩着我的龟头。"},{"kind":"narration","speaker":"旁白","text":"如此巧妙的手技，眼看就要把我逼上绝境——"},{"kind":"dialogue","speaker":"鲁卡","text":"啊啊啊……！这样的，太舒服了……"},{"kind":"dialogue","speaker":"爱丽丝","text":"被余揉捏着的男性器官，就这样高潮了——是最高的幸福哦。"},{"kind":"dialogue","speaker":"爱丽丝","text":"来吧，在余的手中就这样把屈服的液体射出来吧/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的左手，继续对我的龟头发动持续进攻。"},{"kind":"narration","speaker":"旁白","text":"时而揉捏，时而用掌心包裹起来摩擦——"},{"kind":"narration","speaker":"旁白","text":"龟头敏感的尖端，忍耐着丰富多彩的快感攻击。"},{"kind":"narration","speaker":"旁白","text":"右手也没有闲着，温和地刺激着杆的下部和阴囊。"},{"kind":"narration","speaker":"旁白","text":"被异性的双手这样地玩弄，我终于忍耐不住要竖白棋了。"},{"kind":"narration","speaker":"旁白","text":"就这样，在爱丽丝的手中投降了——"},{"kind":"narration","speaker":"旁白","text":"屈服于欲望的瞬间，无法压抑的庞大爆发。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜……！ 啊，啊啊啊啊啊啊啊――！！"},{"kind":"narration","speaker":"旁白","text":"被爱丽丝左手握住的龟头，就这样咕嘟咕嘟地射精了。"},{"kind":"narration","speaker":"旁白","text":"白色的液体从左手掌心溢出，把右手也弄脏了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼呼……被手玩弄了一下，就射出了那么多的子孙。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"被魔物榨精就那么舒服吗……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"真是个没有节操的男人呢……/"},{"kind":"narration","speaker":"旁白","text":"呵呵地笑着，爱丽丝继续蹂躏着射精中的阴茎。"},{"kind":"narration","speaker":"旁白","text":"就这样，一滴不剩地将我榨干——"},{"kind":"dialogue","speaker":"鲁卡","text":"呼啊啊啊啊……"},{"kind":"narration","speaker":"旁白","text":"射精终于结束了，我的东西被彻底榨了个干干净净。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的双手，被大量的白浊液体覆盖了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼呼……你的子孙哆咯哆咯地出来了那么多呢。"},{"kind":"dialogue","speaker":"爱丽丝","text":"呜……哩路，啾噜啾噜啾噜噜……/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝就这样，专心地舔起手上的精液，然后吞入肚里去。"},{"kind":"narration","speaker":"旁白","text":"一边吃一边发出淫靡的声音，看起来吃得很美味——"},{"kind":"narration","speaker":"旁白","text":"自己的精液被那样吃掉，我感受到了极大的背德感，兴奋的感觉。"},{"kind":"dialogue","speaker":"爱丽丝","text":"哩路……啾噜啾噜……呼呼。/"},{"kind":"narration","speaker":"旁白","text":"就这样，吃着精液的那位抬起头开心地打量着我。"},{"kind":"narration","speaker":"旁白","text":"那是让男人屈服以后，确认了对我的支配的表情。"},{"kind":"narration","speaker":"旁白","text":"就这样在我的面前，爱丽丝美丽的脸专心地舔着双手的精液。"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼……奇妙的味道。"},{"kind":"dialogue","speaker":"爱丽丝","text":"虽然说确实是很美味，但是不知为什么有种不可思议的感觉……/"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，看来是很不错，会让人上瘾的味道哦。/"},{"kind":"narration","speaker":"旁白","text":"我什么话也没说，就这样脱力了。"},{"kind":"narration","speaker":"旁白","text":"被女人的手弄至射精，让人感觉到了异常强烈的屈辱感。"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是，连三分钟都没坚持到呢……"},{"kind":"dialogue","speaker":"爱丽丝","text":"不过余的手技实在太好了，这也是没办法的。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"看来还是得好好地锻炼一下才行——/"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？还来……？"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的双手，再次伸向了我的下半身——"},{"kind":"narration","speaker":"旁白","text":"忽然，爱丽丝的双手发生了异形的变化！"},{"kind":"narration","speaker":"旁白","text":"手指部位，生出了无数的小触手！"},{"kind":"dialogue","speaker":"鲁卡","text":"呜、呜啊哇……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"没有必要害怕哦。这可是极大的享受哦……/"},{"kind":"dialogue","speaker":"鲁卡","text":"呼呜……！"},{"kind":"narration","speaker":"旁白","text":"无数的触手沾着妖艳的粘液，向着我的股间袭来。"},{"kind":"narration","speaker":"旁白","text":"就这样，将整根肉棒彻底地包裹起来。"},{"kind":"narration","speaker":"旁白","text":"被粘液所润湿，感受到了异样的粘膜触感。"},{"kind":"narration","speaker":"旁白","text":"虽然看起来很恶心，但实际上非常舒服。"},{"kind":"dialogue","speaker":"爱丽丝","text":"男性器官被触手缠绕的快感，好好享受下吧……/"},{"kind":"dialogue","speaker":"鲁卡","text":"呼呜……这样的……"},{"kind":"dialogue","speaker":"鲁卡","text":"好恶心……"},{"kind":"narration","speaker":"旁白","text":"嫌恶感和快感交替袭来，我的身体开始震动。"},{"kind":"narration","speaker":"旁白","text":"触手将阴茎包裹起来，将杆子呈螺旋状缠绕并施以刺激。"},{"kind":"narration","speaker":"旁白","text":"呜唧呜唧地颤动着，阴茎感受到了异样的触感——"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜呜……啊啊啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼呼……特别的快感吧……？/"},{"kind":"narration","speaker":"旁白","text":"触手将杆子的下半部全部卷住，哆咯哆咯地向顶端进发。"}],"choices":[{"text":"继续","next":null}],"battles":[],"next":"F03"},"F03":{"id":"F03","title":"纳塔利亚","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"好的，目标，伊莉娜山地。"},{"kind":"dialogue","speaker":"鲁卡","text":"魔物强盗，绝对不能置之不理。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……真的要去吗。"},{"kind":"dialogue","speaker":"爱丽丝","text":"明明知道会死，你这个白痴……"},{"kind":"narration","speaker":"旁白","text":"龙和吸血鬼，现在的我的确不可能战胜……"},{"kind":"narration","speaker":"旁白","text":"这个事实，我当然知道——"},{"kind":"dialogue","speaker":"鲁卡","text":"无论说什么，我的信念绝对不会有所动摇。"},{"kind":"dialogue","speaker":"鲁卡","text":"实力不足的话，就为自己的理想献出性命吧！"},{"kind":"dialogue","speaker":"爱丽丝","text":"白痴……"},{"kind":"narration","speaker":"旁白","text":"然后爱丽丝就再也没说话了，"},{"kind":"narration","speaker":"旁白","text":"我们继续朝着西边的山地前进。"},{"kind":"narration","speaker":"旁白","text":"走了几个小时，终于到了伊莉娜山地，"},{"kind":"narration","speaker":"旁白","text":"但是——目前有一个很大的问题……"},{"kind":"narration","speaker":"旁白","text":"盗贼团的详细位置我们并不知道……"},{"kind":"dialogue","speaker":"鲁卡","text":"麻烦了啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"说是退治盗贼团，但是要去哪找她们……"},{"kind":"dialogue","speaker":"爱丽丝","text":"想在这么广阔的山地寻找那些魔物吗。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你打算怎么办……？"},{"kind":"dialogue","speaker":"鲁卡","text":"真是的，要怎么办啊……"},{"kind":"narration","speaker":"旁白","text":"就在困惑中，不知道去哪的时候……"},{"kind":"narration","speaker":"旁白","text":"突然眼前飞出了一个小小的身影！！"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么，已经知道了据点的位置了。"},{"kind":"narration","speaker":"旁白","text":"战斗结束后，爱丽丝又回来了。"},{"kind":"dialogue","speaker":"鲁卡","text":"是啊……"},{"kind":"narration","speaker":"旁白","text":"龙与吸血鬼我都有所了解，但是拉米亚……"},{"kind":"narration","speaker":"旁白","text":"拉米亚——下半身是蛇的强大魔物。"},{"kind":"narration","speaker":"旁白","text":"虽然也存在弱的个体，但是有一些是极其强大的个体。"},{"kind":"narration","speaker":"旁白","text":"就比如身旁的爱丽丝……"},{"kind":"dialogue","speaker":"鲁卡","text":"拉米亚、吸血鬼、龙，都是强大而恐怖的对手啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"所以，我早就说过了……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这家伙，真的想无谓的去送死吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"其实我才没打算无谓地去死……"},{"kind":"dialogue","speaker":"鲁卡","text":"但是，伊莉娅丝贝鲁库的人们受到了魔物盗贼团的危害。"},{"kind":"dialogue","speaker":"鲁卡","text":"如果看着这样的情况不管，就没资格叫做勇者了！"},{"kind":"dialogue","speaker":"爱丽丝","text":"……白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"为了他人的事，而把自己卷进危险之中。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这家伙真是无可救药的白痴。"},{"kind":"narration","speaker":"旁白","text":"无视爱丽丝的言语，我朝着据点前进。"},{"kind":"narration","speaker":"旁白","text":"来吧！无论什么样的强敌，勇者是不会屈服的！"},{"kind":"dialogue","speaker":"亚米拉","text":"……四天王之一，土之哥布林已经被打败了。"},{"kind":"dialogue","speaker":"吸血鬼","text":"库库库……那家伙是四天王中最弱的啊……"},{"kind":"dialogue","speaker":"吸血鬼","text":"打倒那家伙也不能说明实力怎么样……"},{"kind":"dialogue","speaker":"龙","text":"的确如此。"},{"kind":"dialogue","speaker":"龙","text":"为什么那么弱的家伙会是四天王的一员呢？"},{"kind":"dialogue","speaker":"亚米拉","text":"那是因为…… 人手不足……"},{"kind":"dialogue","speaker":"龙","text":"勇者，朝这边过来了！"},{"kind":"dialogue","speaker":"吸血鬼","text":"快点过来受死吧……"},{"kind":"dialogue","speaker":"吸血鬼","text":"愚蠢的人类哟，库库库！……"},{"kind":"dialogue","speaker":"拉米亚","text":"那么，接下来，由我来对付他吧。"},{"kind":"dialogue","speaker":"拉米亚","text":"噗哧噗哧……"},{"kind":"dialogue","speaker":"龙","text":"哇哈哈哈哈……"},{"kind":"dialogue","speaker":"吸血鬼","text":"库库库库库……"},{"kind":"dialogue","speaker":"鲁卡","text":"就是这个洞穴…… 吗？"},{"kind":"narration","speaker":"旁白","text":"很一般的洞穴，不过作为据点是不错的地方。"},{"kind":"narration","speaker":"旁白","text":"不过周围没有盗贼团的人啊……"},{"kind":"narration","speaker":"旁白","text":"为什么基地没有人守着……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"这里面真的有龙吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"完全没有那种感觉……"},{"kind":"narration","speaker":"旁白","text":"爱丽丝用鼻子闻了闻，然后叹息了一下。"},{"kind":"dialogue","speaker":"爱丽丝","text":"原来如此，是这样啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么了，爱丽丝？"},{"kind":"dialogue","speaker":"爱丽丝","text":"余在这里等着，"},{"kind":"dialogue","speaker":"爱丽丝","text":"你快点解决完事情就回来吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"喂喂，别说那种风凉话……"},{"kind":"narration","speaker":"旁白","text":"龙，吸血鬼，拉米亚……"},{"kind":"narration","speaker":"旁白","text":"等待我的，都是强大的魔物。"},{"kind":"narration","speaker":"旁白","text":"别说快点解决了，"},{"kind":"narration","speaker":"旁白","text":"能平安跑出来都是很困难的吧！"},{"kind":"narration","speaker":"旁白","text":"但是不能畏缩在这啊……我在这种地方就停下脚步，还怎么对付魔王呢！"},{"kind":"dialogue","speaker":"鲁卡","text":"好，要上了……！"},{"kind":"narration","speaker":"旁白","text":"跟爱丽丝说完话后，抱着必死的觉悟，我走进了洞穴。"},{"kind":"narration","speaker":"旁白","text":"这里意外地很广阔，完全看不到人影。"},{"kind":"narration","speaker":"旁白","text":"这里真的是盗贼团的据点吗……"},{"kind":"dialogue","speaker":"？？？","text":"哼哼，你终于来了！"},{"kind":"dialogue","speaker":"？？？","text":"我来做你的对手！"},{"kind":"dialogue","speaker":"鲁卡","text":"……谁，谁在那！？"},{"kind":"narration","speaker":"旁白","text":"刚才她说了是水之拉米亚吧……没看见她用水属性技能呢……"},{"kind":"dialogue","speaker":"鲁卡","text":"……算了，继续前进！"},{"kind":"narration","speaker":"旁白","text":"休息了一段时间，我便继续向里面前进。"},{"kind":"narration","speaker":"旁白","text":"或许—— 那必死的决心弄不好是浪费了……"},{"kind":"narration","speaker":"旁白","text":"接着向里面走——"},{"kind":"dialogue","speaker":"？？？","text":"库库库……"},{"kind":"dialogue","speaker":"？？？","text":"「土之哥布林」之后，连「水之拉米亚」都打败了。"},{"kind":"dialogue","speaker":"？？？","text":"但是别以为能够轻易打败我！"},{"kind":"dialogue","speaker":"鲁卡","text":"什，什么人……！？"},{"kind":"narration","speaker":"旁白","text":"这几场战斗有点略为蛋疼，感觉被侮辱了。"},{"kind":"narration","speaker":"旁白","text":"变成蝙蝠，精气吸收，魔眼……"},{"kind":"narration","speaker":"旁白","text":"那些成年吸血鬼也用这些技能么……"},{"kind":"dialogue","speaker":"鲁卡","text":"算了，走吧……"},{"kind":"narration","speaker":"旁白","text":"接着我，继续向内部前进。"},{"kind":"narration","speaker":"旁白","text":"至此四天王已经干掉了三人。"},{"kind":"narration","speaker":"旁白","text":"哥布林、拉米亚、吸血鬼，最后只剩下龙了……"},{"kind":"narration","speaker":"旁白","text":"总有一种强烈的预感——"},{"kind":"dialogue","speaker":"？？？","text":"哇哈哈，终于来了啊！"},{"kind":"dialogue","speaker":"鲁卡","text":"你，你是……！？"}],"choices":[{"text":"继续","next":null}],"battles":["harpy-nest-brood-guard","harpy-younger-solo-duel"],"next":"F04"},"F04":{"id":"F04","title":"海上遭遇","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"好，幸福村去看看吧！"},{"kind":"narration","speaker":"旁白","text":"「萨瑟兰」的老板娘说过那个村发生了什么事。"},{"kind":"dialogue","speaker":"鲁卡","text":"果然，有会有什么大事件发生的吧……"},{"kind":"dialogue","speaker":"爱丽丝","text":"啊，有必要去那里看看。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不能采集蜂蜜是一个严重的事态。"},{"kind":"dialogue","speaker":"爱丽丝","text":"如果甜甜的幸福蜜产量出了问题的话，很多地方有名的食物会受到重大影响的。"},{"kind":"narration","speaker":"旁白","text":"果然这家伙，考虑的还是只有吃。"},{"kind":"narration","speaker":"旁白","text":"不管怎么说，我们的下一个目的地是东北方向的幸福村。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"知道为什么村子的名字叫「幸福村」吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"因为村子里面的人都活得很幸福…… 对吗？"},{"kind":"narration","speaker":"旁白","text":"温馨的农场，村民们高兴地养蜂——"},{"kind":"narration","speaker":"旁白","text":"这样的情景，是幸福村这个名字的含义吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你真是一个白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"幸福村的名字由来，是因为附近的哈比村落。"},{"kind":"dialogue","speaker":"鲁卡","text":"原来如此，是这样的吗……"},{"kind":"narration","speaker":"旁白","text":"因为「ＨＡＰＰＹ」和「ＨＡＲＰＹ」发音相似吗……"},{"kind":"dialogue","speaker":"爱丽丝","text":"从哈比的习性考虑，我大概能猜出那个村子是什么问题了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"——嗯？"},{"kind":"narration","speaker":"旁白","text":"爱丽丝在我眨眼的一瞬间，就这样消失了。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝离开了的话，又是魔物？！"},{"kind":"dialogue","speaker":"鲁卡","text":"好的，胜利了！"},{"kind":"narration","speaker":"旁白","text":"不管怎么说，打倒了蜜蜂娘。"},{"kind":"narration","speaker":"旁白","text":"这次的战斗，得到了不少战斗经验啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……依然与这种程度的杂鱼苦战啊。"},{"kind":"narration","speaker":"旁白","text":"不知何时回来的爱丽丝，也依旧吐出辛辣的讽刺。"},{"kind":"dialogue","speaker":"鲁卡","text":"不要那样说啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"起码已经学会如何战斗了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不用再随便把盐给扔出去了。"},{"kind":"narration","speaker":"旁白","text":"这句话带着刺，但总算可以认为是称赞我吧。"},{"kind":"narration","speaker":"旁白","text":"总之，离幸福村已经仅一步之遥了。"},{"kind":"narration","speaker":"旁白","text":"我们向着发生了什么事情的养蜂的村子进发。"},{"kind":"dialogue","speaker":"鲁卡","text":"这里是，幸福村……"},{"kind":"narration","speaker":"旁白","text":"周围是平稳，宁静的农场。"},{"kind":"narration","speaker":"旁白","text":"大婶和女儿们，辛勤地养蜂和做着其他农活。"},{"kind":"dialogue","speaker":"鲁卡","text":"没有发现什么奇怪的地方啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你眼瞎了吗？白痴。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"你有看到过一个男人的影子吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"这也可以说没有异常？"},{"kind":"dialogue","speaker":"鲁卡","text":"这么想想……真的哎……"},{"kind":"narration","speaker":"旁白","text":"的确，村里一个男人也没有的样子。"},{"kind":"narration","speaker":"旁白","text":"从这里看去，只有一个小男孩在帮忙搬运蜂箱——"},{"kind":"narration","speaker":"旁白","text":"就仅仅一个。"},{"kind":"narration","speaker":"旁白","text":"做农活的，从少女到老太婆，只有女性。"},{"kind":"narration","speaker":"旁白","text":"这究竟是发生什么事了？"},{"kind":"dialogue","speaker":"大婶","text":"哎，旅行者吗？相当年轻呐……"},{"kind":"narration","speaker":"旁白","text":"在蜂箱附近工作的大婶，走过来向我说话了。"},{"kind":"dialogue","speaker":"大婶","text":"真不容易啊，不过，这个村子里已经没什么让旅行者喜欢的东西了。"},{"kind":"dialogue","speaker":"大婶","text":"著名的幸福蜜也因人力不足而减少了产量啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"那个……到底是怎么回事？"},{"kind":"narration","speaker":"旁白","text":"就在我提出问题的那一瞬间……"},{"kind":"dialogue","speaker":"少年","text":"哇啊啊啊啊！！"},{"kind":"narration","speaker":"旁白","text":"突然，男孩的惨叫声响起。"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么了……！？"},{"kind":"narration","speaker":"旁白","text":"我急忙向声音的方向跑去！"},{"kind":"narration","speaker":"旁白","text":"那是……"},{"kind":"dialogue","speaker":"鲁卡","text":"……呼。"},{"kind":"narration","speaker":"旁白","text":"收起剑，我这才松了口气。"},{"kind":"dialogue","speaker":"大婶","text":"这是怎么回事……？"},{"kind":"dialogue","speaker":"年青女孩","text":"哈比被旅行者赶走了……？"},{"kind":"dialogue","speaker":"年青女孩","text":"好厉害！"},{"kind":"narration","speaker":"旁白","text":"房子里的村民都到了广场。"},{"kind":"narration","speaker":"旁白","text":"我很快就就被幸福村的人们包围。"},{"kind":"narration","speaker":"旁白","text":"一眼看去只有女性，没有男人。"},{"kind":"dialogue","speaker":"老婆婆","text":"嗯……能将哈比赶走，相当有实力的年轻人啊。"},{"kind":"narration","speaker":"旁白","text":"从村民们中走出来的，是一位一脸严肃的老婆婆。"},{"kind":"dialogue","speaker":"鲁卡","text":"你是……？"},{"kind":"dialogue","speaker":"老婆婆","text":"我是村长的妻子……"},{"kind":"dialogue","speaker":"老婆婆","text":"村长不在的现在，由我担任代理村长。"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼……看到有危险的小孩子也不管，一头躲进家里的代理村长啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不……整个村子没有一个人，出手搭救这个孩子呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"喂喂，爱丽丝……！"},{"kind":"narration","speaker":"旁白","text":"村里的女性对于爱丽丝的指责，只是默默地低下了头。"},{"kind":"dialogue","speaker":"鲁卡","text":"说的有点过分了，爱丽丝。"},{"kind":"dialogue","speaker":"鲁卡","text":"身薄体弱的女性怎么会是魔物的对手啊。"},{"kind":"narration","speaker":"旁白","text":"所以，帮助有困难的人们，是勇者的义务！"},{"kind":"dialogue","speaker":"老婆婆","text":"……没有力量的我们，到底能做些什么？"},{"kind":"dialogue","speaker":"老婆婆","text":"旅行者哟。"},{"kind":"dialogue","speaker":"老婆婆","text":"你看起来很强大，能拜托一件事吗……"},{"kind":"dialogue","speaker":"爱丽丝","text":"呵呵呵……委托来了哦，勇者大人。"},{"kind":"dialogue","speaker":"爱丽丝","text":"所以按照惯例，把村里麻烦的事接下来吧。"},{"kind":"narration","speaker":"旁白","text":"老婆婆的神情有些阴沉，但是还是无视爱丽丝说了下去。"},{"kind":"dialogue","speaker":"老婆婆","text":"您也注意到了吧，这个村子没有男人。"},{"kind":"dialogue","speaker":"老婆婆","text":"您刚才也看见了，这里的男人全都被哈比抓走了。"},{"kind":"dialogue","speaker":"中年女性","text":"我嫁到这里还没两个月，丈夫就被抓走了……"},{"kind":"dialogue","speaker":"女性","text":"我的丈夫是其他村来的……"},{"kind":"dialogue","speaker":"女性","text":"仅仅一个月，也被哈比抓走了……"},{"kind":"dialogue","speaker":"女性","text":"我丈夫留下来的孩子，在十四岁的时候……"},{"kind":"dialogue","speaker":"女性","text":"也被哈比抓走了……"},{"kind":"dialogue","speaker":"鲁卡","text":"什么……实在是太过分了……"},{"kind":"narration","speaker":"旁白","text":"这么说，村里的男人全部是被哈比抓走了。"},{"kind":"narration","speaker":"旁白","text":"不管是男人还是男孩，包括外来的女婿——"},{"kind":"narration","speaker":"旁白","text":"这些男性，全都被抓走了。"},{"kind":"dialogue","speaker":"鲁卡","text":"被抓走的男人，到底怎么样了……？"},{"kind":"dialogue","speaker":"老婆婆","text":"不知道……目前还没有谁回来过。"},{"kind":"dialogue","speaker":"老婆婆","text":"也许被当做奴隶了……也许已经被吃掉了……"},{"kind":"dialogue","speaker":"鲁卡","text":"什么……！太过分了……！"},{"kind":"narration","speaker":"旁白","text":"绝对，不能原谅哈比！"},{"kind":"narration","speaker":"旁白","text":"因为就是有这样的家伙，才会导致人类和魔物的关系破裂！"},{"kind":"dialogue","speaker":"老婆婆","text":"现在都没有男人敢来这里当女婿了，幸福村的未来一片黑暗。"},{"kind":"dialogue","speaker":"老婆婆","text":"有本事的旅行者哟。"},{"kind":"dialogue","speaker":"老婆婆","text":"你能去打倒哈比，取回幸福村和平的生活吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"你们自己的事自己想办法。"},{"kind":"narration","speaker":"旁白","text":"……和平常一样，爱丽丝对别人的麻烦请求毫不犹豫地拒绝了。"},{"kind":"dialogue","speaker":"鲁卡","text":"喂喂，爱丽丝……"},{"kind":"dialogue","speaker":"爱丽丝","text":"这个样子……不能靠自己的能力维护的和平有什么意义？"},{"kind":"dialogue","speaker":"爱丽丝","text":"依赖于陌生人，而自己却躲在屋子里发抖—— 真不像话。"},{"kind":"dialogue","speaker":"鲁卡","text":"不能这么说，爱丽丝。"},{"kind":"dialogue","speaker":"鲁卡","text":"弱小的村民，是无法和魔物战斗的。"},{"kind":"narration","speaker":"旁白","text":"责备爱丽丝的同时，我也问了老婆婆一个问题。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个……哈比的巢穴在哪？"},{"kind":"dialogue","speaker":"老婆婆","text":"在这个村子东边一点的树林，就是哈比的巢穴。"},{"kind":"dialogue","speaker":"大婶","text":"要去退治哈比们吗……？"},{"kind":"dialogue","speaker":"年青女孩","text":"啊……旅行者大人，谢谢您了……"},{"kind":"dialogue","speaker":"爱丽丝","text":"哼，真不错。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这个白痴冒牌勇者，要为你们去退治哈比。"},{"kind":"dialogue","speaker":"爱丽丝","text":"就这样，你们已经把多少旅行家忽悠到哈比的巢穴里去了？"},{"kind":"dialogue","speaker":"鲁卡","text":"多少人…… 难道说，之前还有其他人去退治哈比过吗？"},{"kind":"narration","speaker":"旁白","text":"代理村长低下了头，一位年轻女性回答了我的问题。"}],"choices":[{"text":"继续","next":null}],"battles":["scylla-deepwreck-lair","mermaid-shore-song-lure"],"next":"F05"},"F05":{"id":"F05","title":"精灵之森","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"隐村恩瑞卡，有必要去看一下。"},{"kind":"narration","speaker":"旁白","text":"明明在我的故乡附近，却从未听说过。"},{"kind":"narration","speaker":"旁白","text":"到底是个什么样的村子呢？"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，恩瑞卡，旅游指南上也有记载。"},{"kind":"dialogue","speaker":"爱丽丝","text":"或许有好吃的东西也说不定。"},{"kind":"narration","speaker":"旁白","text":"和往常一样只为食物而行动。"},{"kind":"narration","speaker":"旁白","text":"全世界旅行的原因，也仅仅是为了各地不同的美食吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"总之，出发吧！"},{"kind":"narration","speaker":"旁白","text":"就这样，我们向着西南方向的隐村恩瑞卡前进着。"},{"kind":"narration","speaker":"旁白","text":"大致的地点从伊莉娅丝贝鲁库的商人那里听说了。"},{"kind":"narration","speaker":"旁白","text":"应该就这附近——"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯……？ 相当稀有的魔物啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"额……？"},{"kind":"narration","speaker":"旁白","text":"回头的瞬间，爱丽丝已经消失了。"},{"kind":"narration","speaker":"旁白","text":"与此同时，一只魔物出现了——"},{"kind":"dialogue","speaker":"爱丽丝","text":"没想到这种地方会有黑暗精灵。"},{"kind":"dialogue","speaker":"爱丽丝","text":"到底发生什么了……？"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……？"},{"kind":"narration","speaker":"旁白","text":"当然，我也不知道。"},{"kind":"dialogue","speaker":"鲁卡","text":"整块伊莉娅丝大陆都有魔物出没，这里有魔物也没什么奇怪的吧……"},{"kind":"narration","speaker":"旁白","text":"转过头，继续前进——"},{"kind":"narration","speaker":"旁白","text":"结果又是一只魔物！"},{"kind":"dialogue","speaker":"爱丽丝","text":"又是黑暗精灵。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那群家伙应该是没有集团行动的习惯的……"},{"kind":"dialogue","speaker":"鲁卡","text":"这么说来，暗黑精灵的数量本来就不多？"},{"kind":"dialogue","speaker":"爱丽丝","text":"没错。"},{"kind":"dialogue","speaker":"爱丽丝","text":"精灵本来是很清纯的种族。"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是有一些稀有的个体，累积了大量魔素。"},{"kind":"dialogue","speaker":"爱丽丝","text":"通俗来说，就是「堕落了」。"},{"kind":"dialogue","speaker":"爱丽丝","text":"就这样成为了好色而且堕落的家伙。"},{"kind":"dialogue","speaker":"爱丽丝","text":"被其他精灵所疏远，只能单独行动的魔物。"},{"kind":"dialogue","speaker":"爱丽丝","text":"还有，暗黑精灵继续积蓄魔素的话，可能变异成其他魔物……"},{"kind":"dialogue","speaker":"爱丽丝","text":"就算是这样，她们也不应该会集团行动啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"知道的真详细啊，爱丽丝。"},{"kind":"dialogue","speaker":"爱丽丝","text":"当然，你以为我是谁？"},{"kind":"dialogue","speaker":"鲁卡","text":"不知道……"},{"kind":"narration","speaker":"旁白","text":"总而言之，魔物再继续袭来的话，就会很麻烦。"},{"kind":"narration","speaker":"旁白","text":"快点到目的地吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"但是恩瑞卡到底在哪呢？"},{"kind":"dialogue","speaker":"鲁卡","text":"真的在这一带吗？"},{"kind":"narration","speaker":"旁白","text":"经过了几小时的步行，我都快筋疲力尽了。"},{"kind":"narration","speaker":"旁白","text":"终于在穿过一片树林之后，看见了一座村庄！"},{"kind":"dialogue","speaker":"鲁卡","text":"那就是恩瑞卡吗？"},{"kind":"narration","speaker":"旁白","text":"满怀喜悦，我们快步走向村庄。"},{"kind":"dialogue","speaker":"鲁卡","text":"这就是……恩瑞卡？"},{"kind":"narration","speaker":"旁白","text":"看过去，只是一座很小的村庄。"},{"kind":"narration","speaker":"旁白","text":"但是气氛有点奇怪。"},{"kind":"narration","speaker":"旁白","text":"安静而且神秘—— 有种不可思议的感觉。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……原来如此。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那些暗黑精灵的事，也全部明白了。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝，你一个人在那明白了什么。"},{"kind":"dialogue","speaker":"鲁卡","text":"这到底怎么回事…… 哎？"},{"kind":"narration","speaker":"旁白","text":"从村子里面走出了一位女性。"},{"kind":"narration","speaker":"旁白","text":"异样的气氛，不可思议的人。"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"你们…… 看起来不像是商人呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……是的……"},{"kind":"dialogue","speaker":"鲁卡","text":"从伊莉娅丝贝鲁库的商人那里听说了这里……"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"请回去吧。"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"这里除了贩卖必需品的旅行商人以外的人，都是不准进入的。"},{"kind":"narration","speaker":"旁白","text":"竟然连进入都不允许。"},{"kind":"narration","speaker":"旁白","text":"这个村子的排斥性也太强了。"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么会这样……"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"很不高兴吗……"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"我们一直是这样生活的。"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"如果你是一位有良心的旅行家，请尊重我们的规定。"},{"kind":"dialogue","speaker":"鲁卡","text":"……明白了，抱歉给你们添麻烦了。"},{"kind":"narration","speaker":"旁白","text":"打破别人宁静的生活——"},{"kind":"narration","speaker":"旁白","text":"真正的勇者是不会做这种事的。"},{"kind":"narration","speaker":"旁白","text":"我们正准备转身离开之时。"},{"kind":"narration","speaker":"旁白","text":"女人的视线落在了我的戒指上。"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"那个戒指……！"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"难道你是……鲁卡！？"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？这个确实是我的名字……"},{"kind":"narration","speaker":"旁白","text":"为什么这人知道我的名字。"},{"kind":"narration","speaker":"旁白","text":"我记忆里从来没有来过这个村子啊……"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"果然是鲁卡啊……"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"已经长这么大了吗……"},{"kind":"dialogue","speaker":"鲁卡","text":"请问……你认识我吗？"},{"kind":"dialogue","speaker":"恩瑞卡的女性","text":"……嗯，我的名字叫做米卡艾拉。"},{"kind":"dialogue","speaker":"米卡艾拉","text":"你的事，你父亲的事，你母亲的事，我全知道——"},{"kind":"narration","speaker":"旁白","text":"自称米卡艾拉的女人，停顿了一下。"},{"kind":"narration","speaker":"旁白","text":"她的眼中透露出深深的决意。"},{"kind":"dialogue","speaker":"米卡艾拉","text":"……但是现在请回去吧。"},{"kind":"dialogue","speaker":"米卡艾拉","text":"如果时机成熟的话，我会告诉你一切。"},{"kind":"dialogue","speaker":"鲁卡","text":"我知道了。"},{"kind":"narration","speaker":"旁白","text":"现在，什么也不能说吗—— 在她身上，我可以看见那种决心。"},{"kind":"narration","speaker":"旁白","text":"就算留在这，也不会知道些什么。"},{"kind":"dialogue","speaker":"鲁卡","text":"那么，我下次再来吧……"},{"kind":"dialogue","speaker":"米卡艾拉","text":"嗯……祝你武运昌盛，鲁卡。"},{"kind":"narration","speaker":"旁白","text":"就这样，我们离开了隐村恩瑞卡。"},{"kind":"narration","speaker":"旁白","text":"这个村子，还是记下来比较好——"},{"kind":"dialogue","speaker":"鲁卡","text":"……不可思议的村子。"},{"kind":"narration","speaker":"旁白","text":"有点怀念的感觉，那种气氛。"},{"kind":"narration","speaker":"旁白","text":"而且，还有个知道我的神秘女性米卡艾拉——"},{"kind":"dialogue","speaker":"爱丽丝","text":"这是怎么了……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"那个村子到底……"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么了，爱丽丝？"},{"kind":"dialogue","speaker":"鲁卡","text":"在村子里发现了什么嘛？"},{"kind":"narration","speaker":"旁白","text":"发现了什么，然后一人独自烦恼着。 真是奇怪的家伙。"},{"kind":"dialogue","speaker":"爱丽丝","text":"发现了一些奇怪的地方。"},{"kind":"dialogue","speaker":"爱丽丝","text":"隐村恩瑞卡的意思指的是精灵【恩瑞卡的发音和日语精灵相近】居住的地方……大概吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"喂喂，你该不会认为那个村子里面全是精灵……？"},{"kind":"narration","speaker":"旁白","text":"如果是真的话，那么那种奇怪的气氛就能解释了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这样想的话……"},{"kind":"dialogue","speaker":"爱丽丝","text":"那个叫米卡艾拉的女人，果然是……"},{"kind":"narration","speaker":"旁白","text":"爱丽丝自言自语地说着，然后叹了一口气。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不管怎么样，原本还期待美食的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"结果白跑一趟。"},{"kind":"narration","speaker":"旁白","text":"……结果还是在惦记食物的事情吗。"},{"kind":"narration","speaker":"旁白","text":"虽然很在意那村子。"},{"kind":"narration","speaker":"旁白","text":"但是现在还有其他事情要做。"},{"kind":"narration","speaker":"旁白","text":"下一个地点是——"},{"kind":"dialogue","speaker":"爱丽丝","text":"怎么，你想再回去吃一次闭门羹？"},{"kind":"dialogue","speaker":"爱丽丝","text":"虽然我喜欢吃东西，但是闭门羹还是算了……"},{"kind":"dialogue","speaker":"鲁卡","text":"……看起来你好像很想吃的样子。"},{"kind":"dialogue","speaker":"爱丽丝","text":"才，才没那样想过呢！"},{"kind":"narration","speaker":"旁白","text":"现在去那里也没什么意义。"},{"kind":"narration","speaker":"旁白","text":"那么，下个目的地是——"}],"choices":[{"text":"继续","next":null}],"battles":["sylph-wind-trial"],"next":"F06"},"F06":{"id":"F06","title":"撒巴萨","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"好的，向伊莉娅丝港口进发！"},{"kind":"narration","speaker":"旁白","text":"伊莉娅丝港口，是去中央大陆的唯一途径。"},{"kind":"narration","speaker":"旁白","text":"终于可以到新大陆去了！"},{"kind":"narration","speaker":"旁白","text":"……不过会有段时间不会回伊莉娅丝大陆了……"},{"kind":"narration","speaker":"旁白","text":"是不是在这边还有什么事没做？"},{"kind":"dialogue","speaker":"鲁卡","text":"……好的，没有剩下的事情了，"},{"kind":"dialogue","speaker":"鲁卡","text":"那么，向伊莉娅丝港口进发！"},{"kind":"dialogue","speaker":"爱丽丝","text":"港口城市的话，可是会有各地的土特产。"},{"kind":"narration","speaker":"旁白","text":"……又在想食物的事情么……"},{"kind":"narration","speaker":"旁白","text":"嗯，去吃遍各地的土特产倒是没问题，"},{"kind":"narration","speaker":"旁白","text":"总比吃人强……"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，有点让人心情激动呢，快，出发吧！"},{"kind":"dialogue","speaker":"鲁卡","text":"是是……"},{"kind":"narration","speaker":"旁白","text":"就这样，我们朝着北方向伊莉娅丝港口前进。"},{"kind":"narration","speaker":"旁白","text":"伊利亚特大陆由女神庇佑着，魔物不是很多。"},{"kind":"narration","speaker":"旁白","text":"但是随着距离神殿越来越远，北边出现的魔物也越来越强大。"},{"kind":"narration","speaker":"旁白","text":"在这种情况下走很远一段距离的话——"},{"kind":"dialogue","speaker":"鲁卡","text":"哎呀，貌似还有一点事情没完成……"},{"kind":"narration","speaker":"旁白","text":"我们回到了大地图。"},{"kind":"dialogue","speaker":"爱丽丝","text":"啊啦，战斗起来好像顺利多了啊。"},{"kind":"narration","speaker":"旁白","text":"不知不觉中爱丽丝就出现在了旁边。"},{"kind":"narration","speaker":"旁白","text":"最近貌似已经很习惯爱丽丝会突然消失的事情了。"},{"kind":"dialogue","speaker":"鲁卡","text":"是吗？难道我已经变得很厉害了吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"得意得太早了，蠢货！"},{"kind":"dialogue","speaker":"爱丽丝","text":"特别那个突刺攻击，太差劲了。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，我觉得我的突刺像疾风一样呢……"},{"kind":"dialogue","speaker":"爱丽丝","text":"差远了……"},{"kind":"dialogue","speaker":"鲁卡","text":"对了，爱丽丝，我战斗的期间你在干什么呢？"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯……？在附近转转，吃点零食，偶尔抓一下虫子，诸如此类。"},{"kind":"narration","speaker":"旁白","text":"总之就是闲得蛋疼吗……"},{"kind":"narration","speaker":"旁白","text":"真那么闲的话，帮我一下不行么……"},{"kind":"narration","speaker":"旁白","text":"接着，那天夜里我们再次野营了——"},{"kind":"dialogue","speaker":"鲁卡","text":"最后勇者打败了魔王，给世界带了和平安定。"},{"kind":"dialogue","speaker":"鲁卡","text":"……可喜可贺。"},{"kind":"narration","speaker":"旁白","text":"这是五百年前，传说中的勇者，海因里希的故事。"},{"kind":"narration","speaker":"旁白","text":"从小时候就喜欢这本书了，都读过很多次了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……哪里可喜可贺啊，你这个白痴。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝一边咬着烤肉，一边对我冷言相对。"},{"kind":"narration","speaker":"旁白","text":"明明是个有趣的故事我却被骂白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"我是魔族。"},{"kind":"dialogue","speaker":"爱丽丝","text":"对于魔族，会对以前魔王战败的故事感到高兴吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"如果听说人类的王被魔族杀了的故事，你会感到高兴吗？？"},{"kind":"dialogue","speaker":"鲁卡","text":"的确……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你的魔物与人类共存的理想漏洞百出，"},{"kind":"dialogue","speaker":"爱丽丝","text":"一点不考虑别人。"},{"kind":"dialogue","speaker":"鲁卡","text":"对不起……"},{"kind":"narration","speaker":"旁白","text":"确实，这些过去的故事，身为魔族的爱丽丝不可能感到愉快。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嘛……被海因里希打倒的当时的魔王，确实不是什么值得称赞的家伙。"},{"kind":"dialogue","speaker":"爱丽丝","text":"迷失于强大的支配欲，对世界造成了极大的破坏和混乱。"},{"kind":"dialogue","speaker":"爱丽丝","text":"最后被人类的勇者打倒了，完全是自作自受。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝发表了令人惊讶的观点。"},{"kind":"dialogue","speaker":"鲁卡","text":"自作自受吗……意外的观点啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"用力量支配他人，也只不过是野蛮的行为，"},{"kind":"dialogue","speaker":"爱丽丝","text":"最后为了这份蛮行遭了报应只能是活该。"},{"kind":"dialogue","speaker":"鲁卡","text":"确实是这样……"},{"kind":"dialogue","speaker":"鲁卡","text":"当今的魔王是什么样的家伙呢？"},{"kind":"narration","speaker":"旁白","text":"现任的魔王，完全是一个谜样的存在。"},{"kind":"narration","speaker":"旁白","text":"不要说人类了，就连魔物都没有多少见过其真面貌的。"},{"kind":"narration","speaker":"旁白","text":"传闻说是历代魔王中魔力最强的一位……"},{"kind":"dialogue","speaker":"鲁卡","text":"而且，她向人类发动了全面战争， 是个坏家伙吧……"},{"kind":"narration","speaker":"旁白","text":"如果她能听的进我的话……也许可以……但是——"},{"kind":"narration","speaker":"旁白","text":"坏人是不可能听进去我的话吧……就只能打败她了吧。"},{"kind":"narration","speaker":"旁白","text":"现今的魔王可是造成人类和魔族关系紧张的元凶。"},{"kind":"dialogue","speaker":"鲁卡","text":"莱米那虐杀，也是那个魔王指示的吧……"},{"kind":"dialogue","speaker":"鲁卡","text":"果然，是个坏家伙吧，爱丽丝有什么想法？"},{"kind":"narration","speaker":"旁白","text":"我想知道爱丽丝是如何看待她们魔族的主人的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不知道……"},{"kind":"narration","speaker":"旁白","text":"爱丽丝用有点不可思议的表情望着天空。"},{"kind":"dialogue","speaker":"爱丽丝","text":"也许，魔王也很迷茫。"},{"kind":"dialogue","speaker":"爱丽丝","text":"人类是该被灭亡的存在吗——"},{"kind":"dialogue","speaker":"鲁卡","text":"爱丽丝……你知道魔王？"},{"kind":"dialogue","speaker":"鲁卡","text":"难道说，你见过？"},{"kind":"narration","speaker":"旁白","text":"谁也没见过魔王，传说中魔王只在城堡的最深处居住着。"},{"kind":"narration","speaker":"旁白","text":"虽然四天王可能见过魔王的脸，但是——"},{"kind":"dialogue","speaker":"爱丽丝","text":"啊……我知道哦。"},{"kind":"dialogue","speaker":"爱丽丝","text":"魔王，也许意外地离你很近呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"我……？ 不可能，像我这种乡下人。"},{"kind":"dialogue","speaker":"鲁卡","text":"就算是魔物，最近才是第一次见哦。"},{"kind":"dialogue","speaker":"爱丽丝","text":"真是的，你这个家伙不是一般地迟钝啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"算了，不说这些了。"},{"kind":"narration","speaker":"旁白","text":"仰望星空的爱丽丝突然站了起来。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么继续指导剑术吧，"},{"kind":"dialogue","speaker":"爱丽丝","text":"你那摇摇晃晃的突刺剑术让我太失望了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"假如遇到了魔王，她都会为你的剑术而感到丢脸的。"},{"kind":"dialogue","speaker":"鲁卡","text":"真是的，为什么这样说啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"把剑拿起来！"},{"kind":"dialogue","speaker":"爱丽丝","text":"让余告诉你什么才叫做「刺」！"},{"kind":"narration","speaker":"旁白","text":"看来今晚要练一晚上的剑术了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"就是这样……要稳定住上半身。"},{"kind":"dialogue","speaker":"爱丽丝","text":"身体尽量不要晃动。"},{"kind":"dialogue","speaker":"鲁卡","text":"这……这样吗？/"},{"kind":"narration","speaker":"旁白","text":"跨马步向前，快速地刺下去！ 总算用出来了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯……总算，姿势算是合格了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"之后就是要用于实战了。"},{"kind":"dialogue","speaker":"鲁卡","text":"谢，谢谢…… 真是个厉害的技能啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这是疾风魔剑的使用者「涂血的费尔南迪斯」的得意技能，血裂雷鸣刺。"},{"kind":"dialogue","speaker":"爱丽丝","text":"该技能斩杀敌人的血在地面上汇聚成了一条湖。"},{"kind":"dialogue","speaker":"鲁卡","text":"听起来好恶心，好血腥的技能……"},{"kind":"narration","speaker":"旁白","text":"血裂雷鸣刺——"},{"kind":"narration","speaker":"旁白","text":"作为我的技能的话，就不要「血裂」了，就叫「雷鸣突刺」好了。"},{"kind":"narration","speaker":"旁白","text":"「雷鸣突刺」习得！"},{"kind":"dialogue","speaker":"爱丽丝","text":"这技能正如其名，闪电般地刺过去，"},{"kind":"dialogue","speaker":"爱丽丝","text":"战斗刚开始的那一刻能发挥最大的效果。"},{"kind":"dialogue","speaker":"爱丽丝","text":"也就是说在第一回合使用的时候威力最大。"},{"kind":"dialogue","speaker":"爱丽丝","text":"之后就也比普通攻击强一些。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这个技能的性价比有点微妙呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯，我明白了，爱丽丝。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么，今天的训练就到此为止了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"为了明天，赶紧去睡觉吧。"},{"kind":"narration","speaker":"旁白","text":"就这样，今天的训练结束了。"},{"kind":"narration","speaker":"旁白","text":"伴随着满足感，我进入了梦乡……"},{"kind":"dialogue","speaker":"？？？","text":"鲁卡…… 勇者鲁卡……"},{"kind":"dialogue","speaker":"鲁卡","text":"呜……啊……"},{"kind":"narration","speaker":"旁白","text":"不知道从哪传来的声音……"},{"kind":"narration","speaker":"旁白","text":"那是！"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"去讨伐魔王吧，鲁卡……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……是……"},{"kind":"dialogue","speaker":"伊莉娅丝","text":"很好，要牢记讨伐魔王哦……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊！伊莉娅丝大人！？"},{"kind":"narration","speaker":"旁白","text":"睁开双眼，迎接我的是明媚的晨光。"}],"choices":[{"text":"继续","next":null}],"battles":["sphinx-riddle-rotation","mantis-girl-scythe-trial","tsuchigumo-artisan-weave-order"],"next":"F07"},"F07":{"id":"F07","title":"金字塔","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"哎？那个是……"},{"kind":"narration","speaker":"旁白","text":"道路的尽头，一只狐狸站在了门前。"},{"kind":"narration","speaker":"旁白","text":"然后爱丽丝又和往常一样不见了。"},{"kind":"dialogue","speaker":"鲁卡","text":"你难道是刚才那只狐狸的同伴？"},{"kind":"narration","speaker":"旁白","text":"七根尾巴……"},{"kind":"narration","speaker":"旁白","text":"看起来很强，和之前的对手完全不是一个感觉。"},{"kind":"dialogue","speaker":"？？？","text":"……嗯，我是七尾，你呢？"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？"},{"kind":"narration","speaker":"旁白","text":"这家伙也不是那个叫玉藻的家伙吗？"},{"kind":"dialogue","speaker":"七尾","text":"前方就是宝物库了，不能让你通过。"},{"kind":"dialogue","speaker":"七尾","text":"所以请回去吧，如果你非要强行突破的话……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，拼尽全力我也要突破！"},{"kind":"narration","speaker":"旁白","text":"真正的勇者是不会后退的。"},{"kind":"dialogue","speaker":"七尾","text":"了解……"},{"kind":"dialogue","speaker":"七尾","text":"让你见识一下玉藻大人的心腹，七尾的力量吧！"},{"kind":"dialogue","speaker":"鲁卡","text":"额？怎么了……"},{"kind":"dialogue","speaker":"鲁卡","text":"哈——好好地睡了一觉啊。"},{"kind":"narration","speaker":"旁白","text":"睁开眼睛，我既不是在旅馆的床上也不是在野营的睡袋里，"},{"kind":"narration","speaker":"旁白","text":"看着潮湿的洞窟，我一瞬间就明白了。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，被魔眼给催眠了！"},{"kind":"narration","speaker":"旁白","text":"眼前是一只大狐狸。"},{"kind":"narration","speaker":"旁白","text":"这是七尾被封印的姿态？"},{"kind":"narration","speaker":"旁白","text":"到底发生什么了……？"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？"},{"kind":"narration","speaker":"旁白","text":"现场又出现了一只小狐狸，"},{"kind":"narration","speaker":"旁白","text":"是一开始封印的那只。"},{"kind":"narration","speaker":"旁白","text":"跑到了被封印的七尾旁边坐下了。"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么了啊？"},{"kind":"narration","speaker":"旁白","text":"看着眼前的两只狐狸，我百思不得其解。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你没有记忆吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"……看来是完全睡着了呢……"},{"kind":"dialogue","speaker":"鲁卡","text":"爱丽丝，到底发生什么事了？"},{"kind":"narration","speaker":"旁白","text":"难道说，爱丽丝在危机关头救了我…… 貌似不是呢。"},{"kind":"dialogue","speaker":"爱丽丝","text":"睡着后就变强了，无法理解的家伙呢……"},{"kind":"dialogue","speaker":"鲁卡","text":"啥？我吗？"},{"kind":"narration","speaker":"旁白","text":"依爱丽丝这么说，我是在睡着之后就把七尾给打倒了？"},{"kind":"narration","speaker":"旁白","text":"说实话，完全没有记忆……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这家伙从现在开始就睡着后去冒险吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那样更有意思些吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"不，不可能……这样的……"},{"kind":"narration","speaker":"旁白","text":"这不就好像讽刺我平时就头脑空空吗……"},{"kind":"narration","speaker":"旁白","text":"不对，现在不是考虑这些的时候——"},{"kind":"dialogue","speaker":"鲁卡","text":"快点进去！"},{"kind":"dialogue","speaker":"鲁卡","text":"那个叫做玉藻的家伙，已经进去了！"},{"kind":"narration","speaker":"旁白","text":"也许，还能在那家伙之前把「海神之铃」拿到手！"},{"kind":"dialogue","speaker":"爱丽丝","text":"不……已经太晚了……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊！？"},{"kind":"narration","speaker":"旁白","text":"宝物库的门慢慢打开了，"},{"kind":"narration","speaker":"旁白","text":"然后出现了一位少女。"},{"kind":"narration","speaker":"旁白","text":"从外表上看，少女也同样是妖狐一族的成员。"},{"kind":"narration","speaker":"旁白","text":"七尾起身站在了少女的旁边，小狐狸也用爪子在少女的腿上抓挠。"},{"kind":"dialogue","speaker":"鲁卡","text":"这家伙好像没七尾强……"},{"kind":"narration","speaker":"旁白","text":"就在我松了口气的时候。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这白痴，仔细数一下尾巴。"},{"kind":"dialogue","speaker":"鲁卡","text":"一，二，三……九条！"},{"kind":"narration","speaker":"旁白","text":"少女的尾巴毫无疑问是九条。"},{"kind":"dialogue","speaker":"鲁卡","text":"只是比七尾多两条而已……"},{"kind":"dialogue","speaker":"爱丽丝","text":"……白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"九尾是妖狐一族最高级的存在，不是七尾能比的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"她是魔王军四天王之一——玉藻。"},{"kind":"dialogue","speaker":"爱丽丝","text":"和古兰贝莉娅一样是最上位的魔族。"},{"kind":"dialogue","speaker":"鲁卡","text":"什么！！"},{"kind":"narration","speaker":"旁白","text":"这位少女，是和古兰贝莉娅同等级的强者吗？"},{"kind":"dialogue","speaker":"玉藻","text":"抱歉，让你们久等了。"},{"kind":"dialogue","speaker":"玉藻","text":"你们这样子，是被封印了魔力吗？"},{"kind":"narration","speaker":"旁白","text":"说玉藻便抚摸着两只狐狸的头——"},{"kind":"dialogue","speaker":"玉藻","text":"那么就把我的魔力分给你们吧。"},{"kind":"narration","speaker":"旁白","text":"就这样，发出光辉的手温柔地抚摸着妖狐的头―"},{"kind":"narration","speaker":"旁白","text":"一瞬间小狐狸恢复了原本的姿态。"},{"kind":"dialogue","speaker":"妖狐","text":"哇哇哇……"},{"kind":"narration","speaker":"旁白","text":"妖狐马上躲在了她背后。"},{"kind":"dialogue","speaker":"玉藻","text":"七尾，要恢复你的魔力得花一点时间，"},{"kind":"dialogue","speaker":"玉藻","text":"不好意思，稍后再说吧。"},{"kind":"narration","speaker":"旁白","text":"七尾伏在了她脚下，"},{"kind":"narration","speaker":"旁白","text":"并且目不转睛地盯着我。"},{"kind":"dialogue","speaker":"玉藻","text":"那个，你是鲁卡吧？"},{"kind":"dialogue","speaker":"玉藻","text":"竟然能打败七尾，不错的实力呢。"},{"kind":"narration","speaker":"旁白","text":"说着便靠近了我，在我旁边转来转去，时不时还闻一两下。"},{"kind":"dialogue","speaker":"玉藻","text":"好可爱哟！"},{"kind":"dialogue","speaker":"玉藻","text":"做我的情人吧！"},{"kind":"dialogue","speaker":"鲁卡","text":"谁希望……！做那什么……！"},{"kind":"dialogue","speaker":"玉藻","text":"呼呼……可爱的家伙呢！"},{"kind":"dialogue","speaker":"玉藻","text":"在床上，奴家一定会好好地疼爱你的啦！"},{"kind":"narration","speaker":"旁白","text":"视线朝下移动过去……"},{"kind":"narration","speaker":"旁白","text":"她手上拿着铃铛一样的东西……"},{"kind":"narration","speaker":"旁白","text":"很古老的铃铛。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个……难道是！？"},{"kind":"dialogue","speaker":"玉藻","text":"这个啊，是「海神之铃」，"},{"kind":"dialogue","speaker":"玉藻","text":"是去中央大陆必备的东西哟。"},{"kind":"dialogue","speaker":"玉藻","text":"老实说，是阿露艾露玛非吵着要我来拿的。"},{"kind":"dialogue","speaker":"鲁卡","text":"阿露艾露玛……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"四天王之一，用风暴封锁航道的元凶。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个风暴也是四天王弄的？……"},{"kind":"dialogue","speaker":"玉藻","text":"就是那样，"},{"kind":"dialogue","speaker":"玉藻","text":"所以你要来拿「海神之铃」的话，知道应该怎么办吧？"},{"kind":"dialogue","speaker":"鲁卡","text":"所以说……只能硬夺了吗？"},{"kind":"narration","speaker":"旁白","text":"我正想拔出剑…… 但是爱丽丝拉住了我的手。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……住手吧。 现在的你完全不是玉藻的对手。"},{"kind":"dialogue","speaker":"鲁卡","text":"但……但是……"},{"kind":"narration","speaker":"旁白","text":"看到这种情况，玉藻笑了起来。"},{"kind":"dialogue","speaker":"玉藻","text":"嘻嘻……魔王大人，你好像对很看重这个人类啊。"},{"kind":"narration","speaker":"旁白","text":"——魔王大人？"},{"kind":"narration","speaker":"旁白","text":"就在刚才玉藻说了魔王大人了吧。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝是——魔王？"},{"kind":"dialogue","speaker":"鲁卡","text":"爱丽丝……你……"},{"kind":"dialogue","speaker":"爱丽丝","text":"……现在才发现吗？白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"余是魔王。爱丽丝菲兹１６世。"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么会！"},{"kind":"narration","speaker":"旁白","text":"刚开始见到的时候，就感觉不是个普通的魔族。"},{"kind":"narration","speaker":"旁白","text":"把古兰贝莉娅赶走的时候，觉得是位强大的上位魔族……"},{"kind":"narration","speaker":"旁白","text":"但是没想到居然是魔王……"},{"kind":"dialogue","speaker":"玉藻","text":"啊咧……原来魔王大人没有告诉他啊。"},{"kind":"dialogue","speaker":"玉藻","text":"不过也没有什么了……"},{"kind":"dialogue","speaker":"玉藻","text":"总而言之，「海神之铃」我收下了…… 嗯？"},{"kind":"narration","speaker":"旁白","text":"此时那只小狐狸在扯玉藻的袖子。"},{"kind":"dialogue","speaker":"玉藻","text":"怎么了？嗯……嗯……"},{"kind":"dialogue","speaker":"玉藻","text":"……原来如此，那个鲁卡，救了你的命啊。"},{"kind":"dialogue","speaker":"玉藻","text":"那么身为狐狸一族族长，得给予你谢礼呢。"},{"kind":"narration","speaker":"旁白","text":"玉藻笑嘻嘻地走到了我的面前。"},{"kind":"dialogue","speaker":"玉藻","text":"那么，你想要什么谢礼呢？"}],"choices":[{"text":"继续","next":null}],"battles":["queen-ant-frontier-nest","spider-girl-garden-silk-commission"],"next":"F08"},"F08":{"id":"F08","title":"格兰戈德","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"我没有战斗的理由。"},{"kind":"dialogue","speaker":"鲁卡","text":"我要打倒的是，阻碍人类和魔物共存的家伙。"},{"kind":"dialogue","speaker":"玉藻","text":"好志气。"},{"kind":"dialogue","speaker":"玉藻","text":"但是总有一天我们还是会战斗的。"},{"kind":"dialogue","speaker":"玉藻","text":"毕竟我是魔王军四天王之一。"},{"kind":"dialogue","speaker":"鲁卡","text":"……等到那时候再说吧。"},{"kind":"narration","speaker":"旁白","text":"现在并没有战斗的理由。"},{"kind":"dialogue","speaker":"玉藻","text":"那么再见啰。"},{"kind":"narration","speaker":"旁白","text":"妖狐七尾和玉藻一起消失了。"},{"kind":"narration","speaker":"旁白","text":"场上还剩下我和—— 表情复杂的爱丽丝。"},{"kind":"dialogue","speaker":"鲁卡","text":"……爱丽丝……是魔王啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……我并没有打算隐瞒。"},{"kind":"dialogue","speaker":"爱丽丝","text":"只不过是你太白痴了，到现在都没有发现。"},{"kind":"dialogue","speaker":"鲁卡","text":"确实，我到现在都还没有发现，很愚蠢……"},{"kind":"dialogue","speaker":"爱丽丝","text":"普通人的话，在赶走古兰贝莉娅的时候就会发现了吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"一个如此孤高的魔族武人，能够使她无条件服从命令的人，只有魔王了吧。"},{"kind":"narration","speaker":"旁白","text":"我到现在为止都在跟魔王一起旅行……"},{"kind":"narration","speaker":"旁白","text":"消灭魔王的旅行，却和魔王在一起——"},{"kind":"narration","speaker":"旁白","text":"并没有感觉是故意试图欺骗我，"},{"kind":"narration","speaker":"旁白","text":"但是，到底是为了什么理由才这样做呢？"},{"kind":"dialogue","speaker":"鲁卡","text":"为什么……要和我一起旅行呢？"},{"kind":"dialogue","speaker":"爱丽丝","text":"和以前的回答一样，"},{"kind":"dialogue","speaker":"爱丽丝","text":"我对你很有兴趣。"},{"kind":"dialogue","speaker":"爱丽丝","text":"另外想亲眼看一下世界。"},{"kind":"dialogue","speaker":"爱丽丝","text":"就这两个理由让我决定跟着你。"},{"kind":"dialogue","speaker":"鲁卡","text":"那么，率领魔王向人类进攻的事……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"「只有自我防卫时才允许动武」，"},{"kind":"dialogue","speaker":"爱丽丝","text":"我仅仅对全体魔物下达了这样的命令。"},{"kind":"dialogue","speaker":"爱丽丝","text":"只不过这条命令被你们人类给歪曲解释了而已。"},{"kind":"dialogue","speaker":"爱丽丝","text":"我没有发动全面战争的意思…… 至少，到目前还没有。"},{"kind":"dialogue","speaker":"鲁卡","text":"并不是想统治人类，只是单纯的自我保卫吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"但是古兰贝莉娅攻打伊莉娅丝贝鲁库的事怎么解释！"},{"kind":"narration","speaker":"旁白","text":"这还不是全部，"},{"kind":"narration","speaker":"旁白","text":"世界各地，都有魔物袭击人类的事情。"},{"kind":"narration","speaker":"旁白","text":"「那是魔王的命令」。"},{"kind":"narration","speaker":"旁白","text":"不论是谁都会这么想吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"莱米那虐杀以来，人类对魔物的复仇心高涨，已经到了极为危险的地步。"},{"kind":"dialogue","speaker":"爱丽丝","text":"所以余，默许了魔物为了保护自身而使用暴力。"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是—— 把这个命令扩大化，对人类主动攻击的魔物也有不少。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这是没办法的情况。"},{"kind":"dialogue","speaker":"鲁卡","text":"那么……那个莱米那虐杀又怎么解释！"},{"kind":"dialogue","speaker":"鲁卡","text":"因为魔王的命令，屠杀了整个莱米那！"},{"kind":"dialogue","speaker":"爱丽丝","text":"我不知道。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这个旅行的目的之一就是查出那件事情的真相。"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……不知道吗……"},{"kind":"narration","speaker":"旁白","text":"不像是装糊涂的样子……"},{"kind":"dialogue","speaker":"鲁卡","text":"魔王也不知道…… 难道是魔物自发的行为吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"莱米那虐杀是在我登上王位之前发生的事。"},{"kind":"dialogue","speaker":"爱丽丝","text":"可能是上一代魔王的命令，也可能是魔物自己的独断。"},{"kind":"dialogue","speaker":"爱丽丝","text":"另外有一个很大的疑点，"},{"kind":"dialogue","speaker":"爱丽丝","text":"莱米那死去的不仅是人类，还有和人类一同生活的魔物。"},{"kind":"dialogue","speaker":"鲁卡","text":"连魔物，也被杀了吗？"},{"kind":"narration","speaker":"旁白","text":"这种事还是第一次听说。"},{"kind":"narration","speaker":"旁白","text":"我和其他人类都听说是魔物制造了这次暴行。"},{"kind":"narration","speaker":"旁白","text":"到底，在莱米那发生了什么事？"},{"kind":"dialogue","speaker":"爱丽丝","text":"以上是全部。"},{"kind":"dialogue","speaker":"爱丽丝","text":"怎么办？鲁卡？现在你要打倒的魔王站在了你面前，你该怎么做？"},{"kind":"dialogue","speaker":"鲁卡","text":"哎……？"},{"kind":"narration","speaker":"旁白","text":"我旅行的目的，是打倒魔王。"},{"kind":"narration","speaker":"旁白","text":"为了打倒魔王，我才从伊莉娅丝维鲁村出发旅行的。"},{"kind":"narration","speaker":"旁白","text":"然后——现在，眼前的存在……"},{"kind":"narration","speaker":"旁白","text":"爱丽丝菲兹１６世……她……"},{"kind":"dialogue","speaker":"爱丽丝","text":"这样吗……那没有办法了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么，只能把你当作向魔王挑战的勇者来处理了！"},{"kind":"dialogue","speaker":"鲁卡","text":"咕……！"},{"kind":"narration","speaker":"旁白","text":"我的剑刚拔出来——"},{"kind":"narration","speaker":"旁白","text":"就在那一瞬间被爱丽丝的尾巴打飞了。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"迟钝，弱小……尽管如此，你还是向我表达了战意。/"},{"kind":"narration","speaker":"旁白","text":"就在我的眼前，爱丽丝逼近过来。"},{"kind":"narration","speaker":"旁白","text":"就这样的我的身体，被大蛇的尾巴结结实实地卷了起来."},{"kind":"dialogue","speaker":"爱丽丝","text":"虽然远远还不够成熟，你还是以勇者的身份向我挑战了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"既然如此，将你消灭就是魔王的义务。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"就这样，被余吞下肚子去吧。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"……用这张嘴。/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的下腹部裂开了，形成了一张巨大的嘴。"},{"kind":"narration","speaker":"旁白","text":"异样的肉蠢动着，充满了触手的异形的嘴——"},{"kind":"dialogue","speaker":"鲁卡","text":"啊、啊啊啊啊啊……"},{"kind":"narration","speaker":"旁白","text":"这就像是，被蛇盯上的青蛙。"},{"kind":"narration","speaker":"旁白","text":"就算是在将自己吞下的嘴面前，身体也无法动弹。"},{"kind":"narration","speaker":"旁白","text":"就这样下去，我会被整个吞下去吧——"},{"kind":"narration","speaker":"旁白","text":"就算明白了这点，被恶魔迷惑的我也完全无力反抗。"},{"kind":"dialogue","speaker":"爱丽丝","text":"我的捕食口，不是给猎物带来恐惧而是快感。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你这家伙，就在恍惚的快感中被我吃掉吧。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"放松心情，忘记恐惧眼中只看着余就好……/"},{"kind":"narration","speaker":"旁白","text":"被尾巴卷住的我的身体，就这样被送进了腹部的口腔中。"},{"kind":"narration","speaker":"旁白","text":"被触手卷住的双腿，一下子就被嘴巴吞了进去。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊、啊呜呜呜……"},{"kind":"dialogue","speaker":"爱丽丝","text":"不用感到恐怖，好好享受快感吧……"},{"kind":"dialogue","speaker":"爱丽丝","text":"余的捕食口，能让猎物充分感受到被进食的快感。/"},{"kind":"dialogue","speaker":"鲁卡","text":"啊啊啊……爱丽丝……"},{"kind":"narration","speaker":"旁白","text":"就这样，被爱丽丝所吃掉——"},{"kind":"narration","speaker":"旁白","text":"对于这样的事情，我反而抱有期待的感情。"},{"kind":"narration","speaker":"旁白","text":"我的脚，被柔软的肉所包裹。"},{"kind":"narration","speaker":"旁白","text":"触手缠绕摩擦，吸溜吸溜地舔上去——"},{"kind":"narration","speaker":"旁白","text":"从脚被吞入口腔开始，我就放弃了抵抗的念头。"},{"kind":"narration","speaker":"旁白","text":"就这样被吃掉，把身体和心灵全部献给爱丽丝——"},{"kind":"narration","speaker":"旁白","text":"贪求着肉欲，我的东西很快大了起来。"},{"kind":"narration","speaker":"旁白","text":"感受着异样的触感，产生了激烈的反应。"},{"kind":"dialogue","speaker":"爱丽丝","text":"库库库……大起来了呢。"},{"kind":"dialogue","speaker":"爱丽丝","text":"被余捕食就兴奋起来，实在是没节操的家伙呢……/"},{"kind":"dialogue","speaker":"鲁卡","text":"啊、啊呀呀呀呀呀……！"},{"kind":"narration","speaker":"旁白","text":"被爱丽丝吞入口腔的双腿，被异样的触感所包裹。"},{"kind":"narration","speaker":"旁白","text":"肉和触手蠢动着，将大量的粘液涂在我的腿上。"},{"kind":"narration","speaker":"旁白","text":"而且，相当的舒服——"},{"kind":"dialogue","speaker":"爱丽丝","text":"从你的脚开始，全部要融化了哦……/"},{"kind":"dialogue","speaker":"鲁卡","text":"啊啊啊啊啊…… 脚，好舒服啊……"},{"kind":"narration","speaker":"旁白","text":"在甘美的快感中无力，我陷入了恍惚之中。"},{"kind":"narration","speaker":"旁白","text":"恐怕，腿的消化已经开始了——"},{"kind":"narration","speaker":"旁白","text":"但是就算知道，我也无法抵抗这种快感。"},{"kind":"dialogue","speaker":"爱丽丝","text":"腿被捕食，那么舒服吗……/"},{"kind":"dialogue","speaker":"爱丽丝","text":"伴随着快感，肉棒也一同被消化了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"男人的证明，也享受着同样的快感慢慢地融化……/"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜呜呜呜呜……"},{"kind":"narration","speaker":"旁白","text":"现在，脚被消化时候的快感，肉棒也一同品尝了——"},{"kind":"narration","speaker":"旁白","text":"一想到这里，我伴随着期待和兴奋到了绝顶。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜呜呜……爱丽丝，快点吃吧……"},{"kind":"dialogue","speaker":"鲁卡","text":"把我的鸡鸡，快点吃掉……"},{"kind":"dialogue","speaker":"爱丽丝","text":"库库……那么快就喜欢上了被捕食的滋味了吗。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么就按照你的愿望，把你的生殖器消化掉……/"}],"choices":[{"text":"继续","next":null}],"battles":["undine-spring-deep-cleansing"],"next":"F09"},"F09":{"id":"F09","title":"温蒂妮之泉","status":"compiled","scenes":[{"kind":"narration","speaker":"旁白","text":"为了寻求风精灵的力量，我们前往精灵之森。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，这是本来的目的地。"},{"kind":"dialogue","speaker":"爱丽丝","text":"得到希尔芙的力量后就赶紧离开这个地方。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么，你还有什么事情没完成吗？？"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯，还剩一点事……"},{"kind":"narration","speaker":"旁白","text":"我返回了地图。"},{"kind":"dialogue","speaker":"鲁卡","text":"好的！向精灵之森进发！！"},{"kind":"narration","speaker":"旁白","text":"就这样，我们终于要去寻找风精灵了。"},{"kind":"dialogue","speaker":"鲁卡","text":"由于那样……"},{"kind":"dialogue","speaker":"鲁卡","text":"背叛伊莉娅丝大人的那个堕天使，就变成了魔王。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……白痴吗？你这家伙。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你打算向着身为魔王的余，说明魔王的诞生历史吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"是啊……说的也是。"},{"kind":"narration","speaker":"旁白","text":"以前谈论到魔王被打败的事惹爱丽丝生气了，所以这次就谈了谈魔王诞生的故事——"},{"kind":"narration","speaker":"旁白","text":"但是现任魔王听了还是很不开心啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"总而言之，这类的传说都是为了贬低魔族的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"初代魔王是伊莉娅丝的下属，这种说法很荒唐。"},{"kind":"dialogue","speaker":"爱丽丝","text":"初代魔王和伊莉娅丝是同级的神，"},{"kind":"dialogue","speaker":"爱丽丝","text":"和人类一样，并不是伊莉娅丝的手下。"},{"kind":"dialogue","speaker":"鲁卡","text":"初代魔王和伊莉娅丝大人是同等级的神……？"},{"kind":"narration","speaker":"旁白","text":"这种话第一次听说……"},{"kind":"narration","speaker":"旁白","text":"对于我来说，这种事也显得很荒唐。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……哼，说了你也不会信。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这个世界，原本是光与暗的混合存在。"},{"kind":"dialogue","speaker":"爱丽丝","text":"光中诞生伊莉娅丝，暗中诞生初代魔王，"},{"kind":"dialogue","speaker":"爱丽丝","text":"也就是说，她和伊莉娅丝是里与表的相互存在。"},{"kind":"dialogue","speaker":"爱丽丝","text":"就和一枚硬币的正反面一样。"},{"kind":"dialogue","speaker":"鲁卡","text":"既然是和伊莉娅丝大人同格的神，为什么会成为魔王？"},{"kind":"dialogue","speaker":"鲁卡","text":"为什么不在天上生活而跑到地上来了呢？"},{"kind":"dialogue","speaker":"爱丽丝","text":"那个嘛……我也不知道。"},{"kind":"dialogue","speaker":"爱丽丝","text":"初代大人大概是有着自己的什么想法吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"那么初代魔王怎样了呢？"},{"kind":"dialogue","speaker":"鲁卡","text":"和伊莉娅丝大人同格的话，就不会因为寿命的原因为死了吧？？"},{"kind":"dialogue","speaker":"爱丽丝","text":"……初代魔王把位置传给二代后就消失了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"或是回到天上啦，或者是一直在背后守护着我们拉……"},{"kind":"dialogue","speaker":"鲁卡","text":"毫无说服力啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你在怀疑吗！"},{"kind":"dialogue","speaker":"爱丽丝","text":"初代魔王和伊莉娅丝是同格的神！威严不可亵渎！"},{"kind":"dialogue","speaker":"鲁卡","text":"是是，好厉害啊！"},{"kind":"dialogue","speaker":"爱丽丝","text":"哼哼…… /"},{"kind":"dialogue","speaker":"爱丽丝","text":"哼，无所谓了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"现在给我进行剑术修炼！"},{"kind":"dialogue","speaker":"爱丽丝","text":"以你现在的实力，只配跪在魔王的脚下。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，我知道了……"},{"kind":"narration","speaker":"旁白","text":"就这样，稀里糊涂地开始了剑术修炼。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你的ＳＰ的上限也提升了，可以学习更高级的技能了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"现在我传授你乱击技能。"},{"kind":"dialogue","speaker":"鲁卡","text":"乱击？就和我的「胡乱斩击」一样么？"},{"kind":"dialogue","speaker":"爱丽丝","text":"那种技能完全是耻辱！"},{"kind":"dialogue","speaker":"爱丽丝","text":"怎么能乱比较啊，你这个白痴。"},{"kind":"dialogue","speaker":"鲁卡","text":"……抱歉。"},{"kind":"narration","speaker":"旁白","text":"被斥责的同时，我开始修炼新的剑术——"},{"kind":"dialogue","speaker":"鲁卡","text":"喝！！！"},{"kind":"narration","speaker":"旁白","text":"与我声音同时发出，纵横无尽的斩击。"},{"kind":"narration","speaker":"旁白","text":"和「胡乱斩击」完全不同，每一斩都衔接得毫无空隙。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……样子看起来已经不错了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"无数斩击的沐浴，对敌人剑舞般的攻击——"},{"kind":"dialogue","speaker":"爱丽丝","text":"那就是「死剑·乱星」。"},{"kind":"dialogue","speaker":"爱丽丝","text":"威力很大，要消耗４点ＳＰ。"},{"kind":"dialogue","speaker":"爱丽丝","text":"要慎重一点，用后就没ＳＰ了。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，我知道了……"},{"kind":"narration","speaker":"旁白","text":"４点ＳＰ的消耗等于我现在所拥有的ＳＰ数。"},{"kind":"narration","speaker":"旁白","text":"ＳＰ完全恢复过来的时间很长，绝对不能滥用。"},{"kind":"dialogue","speaker":"爱丽丝","text":"创出此技的六手剑士迦拉曾经将一整个骑士团变成了肉块。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个，能别附带这种故事么……"},{"kind":"narration","speaker":"旁白","text":"已经学会了很多剑术，但是很可悲全部是魔族的技巧……"},{"kind":"narration","speaker":"旁白","text":"不过这确实提升了我的实力！！"},{"kind":"narration","speaker":"旁白","text":"「死剑·乱星」习得！"},{"kind":"dialogue","speaker":"爱丽丝","text":"一般来说，这可不是那么简单就能学会的技能……"},{"kind":"dialogue","speaker":"爱丽丝","text":"我想如果是你的话，应该能比较容易领会。"},{"kind":"dialogue","speaker":"鲁卡","text":"哦嘿嘿，爱丽丝，你终于承认了我的实力吗！？"},{"kind":"dialogue","speaker":"鲁卡","text":"哦嘿嘿嘿嘿嘿嘿嘿……"},{"kind":"dialogue","speaker":"爱丽丝","text":"不对，你这个白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你在睡着的时候，曾经用过类似的乱击技………"},{"kind":"dialogue","speaker":"爱丽丝","text":"和我知道的技艺完全不同……"},{"kind":"dialogue","speaker":"鲁卡","text":"连魔王也不知道的事啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你的潜在能力是在太特殊了，"},{"kind":"dialogue","speaker":"爱丽丝","text":"那个魔力和技术，已经不是人类能够达到的领域了。"},{"kind":"dialogue","speaker":"鲁卡","text":"你认为我其实是魔族？"},{"kind":"narration","speaker":"旁白","text":"我母亲是普通人，父亲也是。"},{"kind":"dialogue","speaker":"爱丽丝","text":"我最初的结论是你是人与魔族的混血，"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是从那个可疑的戒指上确实感觉不到任何力量。"},{"kind":"dialogue","speaker":"爱丽丝","text":"真是的，无法理解的家伙啊………"},{"kind":"dialogue","speaker":"鲁卡","text":"就算你这样说………"},{"kind":"narration","speaker":"旁白","text":"不说这些了，现在我又有了强大的一招！！"},{"kind":"narration","speaker":"旁白","text":"伴随着满足感，我就去睡觉了。"},{"kind":"narration","speaker":"旁白","text":"明天，就要去精灵之森了。"},{"kind":"dialogue","speaker":"鲁卡","text":"这就是，精灵之森吗……"},{"kind":"narration","speaker":"旁白","text":"完全看不见入口，满眼都是茂盛的树木。"},{"kind":"narration","speaker":"旁白","text":"在这里面，有风精灵希尔芙……"},{"kind":"dialogue","speaker":"爱丽丝","text":"不仅是风精灵，这里还有各种精灵和妖精。"},{"kind":"dialogue","speaker":"爱丽丝","text":"基本上都不是会危害人类的生物。"},{"kind":"dialogue","speaker":"爱丽丝","text":"只不过妖精喜欢恶作剧而已。"},{"kind":"dialogue","speaker":"鲁卡","text":"这么说，就不用战斗了哦。"},{"kind":"dialogue","speaker":"鲁卡","text":"好了，走吧！"},{"kind":"narration","speaker":"旁白","text":"松了一口气，当我准备踏进森林的时候……"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么？爱丽丝你不跟着来吗？？"},{"kind":"narration","speaker":"旁白","text":"爱丽丝站在原地，没有要跟上来的意思。"},{"kind":"dialogue","speaker":"爱丽丝","text":"身为魔王的余，如果进入森林的话，会惊动妖精的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"所以我还是在这等着吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"了解。那我会尽量早点回来的。"},{"kind":"narration","speaker":"旁白","text":"就这样，我一个人进入了森林。"},{"kind":"dialogue","speaker":"鲁卡","text":"相当的广阔啊，我该往哪走呢……？"},{"kind":"narration","speaker":"旁白","text":"就在我擦汗环视四周的时候……"},{"kind":"dialogue","speaker":"希尔芙","text":"呜呜呜……呜啊啊啊啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"对，对不起………"},{"kind":"narration","speaker":"旁白","text":"现在该怎么办呢，"},{"kind":"narration","speaker":"旁白","text":"本来是说找她借力量的，结果还把她弄哭了……"},{"kind":"dialogue","speaker":"希尔芙","text":"呜呜呜…… 反正我就是不会战斗的啦……"},{"kind":"dialogue","speaker":"希尔芙","text":"反正就没法把风的力量用到战斗上啦！"},{"kind":"narration","speaker":"旁白","text":"通过了刚才的战斗理解了一件事……"},{"kind":"narration","speaker":"旁白","text":"就算是风精灵自己也不能好好地使用风。"},{"kind":"dialogue","speaker":"希尔芙","text":"如果是你的话，会好好地使用我的力量吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯，我会努力的！"},{"kind":"dialogue","speaker":"希尔芙","text":"那么，从现在开始，就一直在一起了啰！"},{"kind":"dialogue","speaker":"希尔芙","text":"说好了只要打到我，我就把力量借给你的。"},{"kind":"narration","speaker":"旁白","text":"一道不可思议的光闪过，希尔芙就消失了。"},{"kind":"dialogue","speaker":"鲁卡","text":"哎，发生了什么。"},{"kind":"narration","speaker":"旁白","text":"突然间感觉到了，全身流淌着不可思议的力量。"},{"kind":"narration","speaker":"旁白","text":"就好像身体已经和周围的风融合为了一体。"}],"choices":[{"text":"继续","next":null}],"battles":["salamander-lava-cavern-training"],"next":"F10"},"F10":{"id":"F10","title":"火山","status":"compiled","scenes":[{"kind":"narration","speaker":"旁白","text":"从圣·伊利亚出来已经十天了。"},{"kind":"narration","speaker":"旁白","text":"然后还要三天才能到撒巴萨城。"},{"kind":"narration","speaker":"旁白","text":"单单魔物就够麻烦了，这严酷的自然环境更让旅途变得艰难。"},{"kind":"narration","speaker":"旁白","text":"如同蒸笼般的热带雨林，让人抓狂不已……"},{"kind":"dialogue","speaker":"爱丽丝","text":"……真热。"},{"kind":"dialogue","speaker":"鲁卡","text":"你明明看起来很凉爽……"},{"kind":"dialogue","speaker":"鲁卡","text":"我都快热得中暑了……"},{"kind":"dialogue","speaker":"爱丽丝","text":"那你脱啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"正好省去魔物袭击你时扒衣服的时间了……"},{"kind":"dialogue","speaker":"鲁卡","text":"为什么要从魔物的角度考虑这个！ 嗯？"},{"kind":"narration","speaker":"旁白","text":"旁边的草丛有晃动的迹象，有奇怪的阴影接近了……"},{"kind":"narration","speaker":"旁白","text":"草丛被扒开了，是魔物！"},{"kind":"dialogue","speaker":"鲁卡","text":"即使天很热，魔物依然很精神啊……"},{"kind":"narration","speaker":"旁白","text":"魔物难道完全不怕热吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"……热。 而且肚子饿了……"},{"kind":"narration","speaker":"旁白","text":"……是饿了才没精神啊！"},{"kind":"dialogue","speaker":"爱丽丝","text":"呐……空气好干燥啊………"},{"kind":"dialogue","speaker":"鲁卡","text":"因为这里已经接近干燥的地区了啊……"},{"kind":"dialogue","speaker":"鲁卡","text":"再往前一点就到沙漠了。"},{"kind":"narration","speaker":"旁白","text":"然后在这这沙漠的中心，有我们的目的地撒巴萨城。"},{"kind":"narration","speaker":"旁白","text":"有着热砂帝王之称的撒巴萨王的子孙，撒巴萨九世统治的国家。"},{"kind":"narration","speaker":"旁白","text":"诺姆虽然说是在沙漠的某区域，但是具体位置还不知道。"},{"kind":"narration","speaker":"旁白","text":"只能以撒巴萨城为据点，然后再收集情报进行调查。"},{"kind":"dialogue","speaker":"爱丽丝","text":"啊，魔物又来啦……"},{"kind":"dialogue","speaker":"鲁卡","text":"真是的………"},{"kind":"narration","speaker":"旁白","text":"无论去哪，都会遭受魔物袭击啊。"},{"kind":"narration","speaker":"旁白","text":"人类和魔物共存的理想实现起来看来真是艰难啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"呼……"},{"kind":"narration","speaker":"旁白","text":"看着逃跑的小牛，我也松了口气。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……嗯，结束了吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"怎么样，"},{"kind":"dialogue","speaker":"鲁卡","text":"我也变强了不少吧？"},{"kind":"dialogue","speaker":"爱丽丝","text":"比以前强了一些。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不过也就只能把风当屏障用了，"},{"kind":"dialogue","speaker":"爱丽丝","text":"要做到寄风于行，才能将风的力量化为极致！"},{"kind":"dialogue","speaker":"鲁卡","text":"抱歉……"},{"kind":"dialogue","speaker":"希尔芙","text":"垂头丧气……"},{"kind":"narration","speaker":"旁白","text":"心里面的希尔芙也在失落……"},{"kind":"narration","speaker":"旁白","text":"话说这家伙也是就只会风之屏障这一招吧……"},{"kind":"dialogue","speaker":"鲁卡","text":"连风精灵自己都用不出凤的力量吗………"},{"kind":"narration","speaker":"旁白","text":"风精灵自己都不会用风………"},{"kind":"narration","speaker":"旁白","text":"不是魔力的问题，而是战斗方法的问题吧……"},{"kind":"narration","speaker":"旁白","text":"寄宿风于行动，到底是什么呢……"},{"kind":"narration","speaker":"旁白","text":"要想得知这些只能靠修炼了。"},{"kind":"dialogue","speaker":"鲁卡","text":"好的，要加油了！"},{"kind":"dialogue","speaker":"鲁卡","text":"一边修行，一边去寻找剩下的三位精灵！"},{"kind":"narration","speaker":"旁白","text":"就这样我们继续前进着，"},{"kind":"narration","speaker":"旁白","text":"撒巴萨离这还远着呢……"},{"kind":"narration","speaker":"旁白","text":"走了不远，双脚已经踏入了沙漠地带。"},{"kind":"narration","speaker":"旁白","text":"比预想中还热的干燥天气，毫不留情地夺取我身体内的水分！"},{"kind":"dialogue","speaker":"鲁卡","text":"呜……热热热………"},{"kind":"narration","speaker":"旁白","text":"虽然已经有觉悟了，但这现实情况——"},{"kind":"narration","speaker":"旁白","text":"太阳毒辣辣地灼烧着我，几乎要把我烤干了……"},{"kind":"narration","speaker":"旁白","text":"随着环境的改变，袭击过来的也换成了沙漠特有的魔物——"},{"kind":"narration","speaker":"旁白","text":"爱丽丝叹了口气，突然用尾巴缠住了我的身体。"},{"kind":"dialogue","speaker":"鲁卡","text":"喂，你突然做什么啊！"},{"kind":"dialogue","speaker":"爱丽丝","text":"长途的旅行，欲望积蓄了不少吧，"},{"kind":"dialogue","speaker":"爱丽丝","text":"让我帮你释放出来吧……/"},{"kind":"dialogue","speaker":"鲁卡","text":"说什么啊，只是你肚子饿了吧……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"哼，说什么失礼的事。"},{"kind":"dialogue","speaker":"爱丽丝","text":"如果有其他魔物来诱惑你，你也一样会老老实实地顺从吧。/"},{"kind":"dialogue","speaker":"爱丽丝","text":"再说，失礼的也是你吧？"},{"kind":"dialogue","speaker":"爱丽丝","text":"魔王就在你旁边，却还受其他魔物的诱惑……/"},{"kind":"dialogue","speaker":"鲁卡","text":"所以我说了那个时候我根本没有受神灯魔女的诱惑过……！"},{"kind":"narration","speaker":"旁白","text":"但是无视我的话，"},{"kind":"narration","speaker":"旁白","text":"爱丽丝抱住了我，大胸器压了上来。"},{"kind":"narration","speaker":"旁白","text":"那对大胸，看得清清楚楚。"},{"kind":"dialogue","speaker":"爱丽丝","text":"怎么了？这样盯着余的胸部……/"},{"kind":"dialogue","speaker":"鲁卡","text":"我……我才没有去看呢……！"},{"kind":"dialogue","speaker":"爱丽丝","text":"这么说来的话，平常你的时候你也经常侧眼偷看余的胸部吧，"},{"kind":"dialogue","speaker":"爱丽丝","text":"很喜欢余的胸部吗……？/"},{"kind":"dialogue","speaker":"鲁卡","text":"才……才不是，……！"},{"kind":"dialogue","speaker":"鲁卡","text":"因为只有你一个人在我身边啊！……"},{"kind":"dialogue","speaker":"爱丽丝","text":"没办法的家伙啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么，就用这个你喜欢的胸部让你快乐吧……/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝把我的衣服脱掉，我成为了赤身裸体的状态。"},{"kind":"narration","speaker":"旁白","text":"就这样把露在外面的肉棒，用那对巨大的胸部严严实实地夹了起来。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊啊啊啊啊……"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的双丘惊人地柔软，而且极具弹性。"},{"kind":"narration","speaker":"旁白","text":"肉棒被完全埋入其中，难以言喻的触感从两边袭来。"},{"kind":"narration","speaker":"旁白","text":"被这样的东西夹住，柔软的压迫感彻底覆盖了肉棒。"},{"kind":"narration","speaker":"旁白","text":"简直就像，陷入了被温暖的天国包裹的感受。"},{"kind":"dialogue","speaker":"爱丽丝","text":"偷偷地看着余的胸部，到底在做什么下流的想象？"},{"kind":"dialogue","speaker":"爱丽丝","text":"用这对胸部，把自己的性器夹入其中，你有这样想过吧……？/"},{"kind":"dialogue","speaker":"鲁卡","text":"这、这样的事情……没有考虑过……"},{"kind":"dialogue","speaker":"爱丽丝","text":"库库库，说实话就那么让你害羞吗……？/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝用双手捧住自己的胸部，从左右两边缓缓地用力。"},{"kind":"narration","speaker":"旁白","text":"肉棒被像布丁一样有弹力的胸部夹住了。"},{"kind":"narration","speaker":"旁白","text":"来自左右两边的甘美压迫，充分地刺激着肉棒——"},{"kind":"narration","speaker":"旁白","text":"就好像，埋入了柔软又温暖的乐园中的感受。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜呜呜……"},{"kind":"dialogue","speaker":"爱丽丝","text":"都这样了，还继续嘴硬吗……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"只要你老老实实的说……让你更舒服点也是可以的哦？/"},{"kind":"dialogue","speaker":"鲁卡","text":"这、这样的事……没有…… 啊呜呜呜……"},{"kind":"dialogue","speaker":"爱丽丝","text":"来吧……用余的乳房好好地榨出来吧……？/"},{"kind":"narration","speaker":"旁白","text":"爱丽丝啾呜啾呜地使用胸部压迫，对肉棒加以刺激。"},{"kind":"narration","speaker":"旁白","text":"时而将胸部全体晃动，时而用胸部夹紧肉棒。"},{"kind":"narration","speaker":"旁白","text":"冠状沟被乳肉摩擦着，那份快感使我几乎要无力了——"},{"kind":"dialogue","speaker":"爱丽丝","text":"来吧来吧……快点承认吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"一直对余的乳房很中意的事情……/"},{"kind":"dialogue","speaker":"鲁卡","text":"不是的……那种事……啊呜呜呜呜……"},{"kind":"narration","speaker":"旁白","text":"大脑被甘美的刺激所俘虏，但是我还是顽强抵抗。"},{"kind":"narration","speaker":"旁白","text":"忽然——令人出乎意料，胸部的压迫放松了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不承认的话，就这样结束了哦。"},{"kind":"dialogue","speaker":"爱丽丝","text":"库库库，这样好吗……？/"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯……？"},{"kind":"narration","speaker":"旁白","text":"乳房的刺激，渐渐地舒缓了下来。"},{"kind":"narration","speaker":"旁白","text":"两边向内的力道放松，肉棒从压迫中被解放出来。"},{"kind":"narration","speaker":"旁白","text":"快感大幅减弱，与之相对的焦躁感像煮沸的油一样开始沸腾。"},{"kind":"narration","speaker":"旁白","text":"就好像，不完全燃烧引发的未能满足的感觉——"},{"kind":"dialogue","speaker":"爱丽丝","text":"……怎么啦，难道不想用余的胸部高潮吗。"},{"kind":"dialogue","speaker":"爱丽丝","text":"在这山谷里，如你所愿地把精液释放出来不好吗……/"},{"kind":"dialogue","speaker":"鲁卡","text":"啊呜呜……"},{"kind":"narration","speaker":"旁白","text":"不再是胸部的压迫，取而代之的是柔软肌肤的触感。"},{"kind":"narration","speaker":"旁白","text":"随着快感的减弱，我心中的焦躁感却是迎来了高潮。"},{"kind":"dialogue","speaker":"鲁卡","text":"看、让我看……"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯……？ 听不见哦……？/"},{"kind":"dialogue","speaker":"鲁卡","text":"爱丽丝的胸部，让我看……"},{"kind":"dialogue","speaker":"鲁卡","text":"所以，请那样继续吧……"},{"kind":"dialogue","speaker":"爱丽丝","text":"库库库……终于承认了啊。/"}],"choices":[{"text":"继续","next":null}],"battles":["sylph-wind-trial"],"next":"F11"},"F11":{"id":"F11","title":"四精灵汇合","status":"compiled","scenes":[{"kind":"narration","speaker":"旁白","text":"离开沙漠地带撒巴萨已经有一周时间了。"},{"kind":"narration","speaker":"旁白","text":"这里是深绿的自然和神秘的大地，诺亚地区。"},{"kind":"narration","speaker":"旁白","text":"这次的目的地是不远处的古兰德诺亚城。"},{"kind":"narration","speaker":"旁白","text":"由古兰德诺亚女王十世统治的城市，诺亚地区最大的都市——"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，诺亚地区有不少的名胜古迹。"},{"kind":"dialogue","speaker":"爱丽丝","text":"其中最有名的属于古兰德诺亚城的圆环斗技场……"},{"kind":"dialogue","speaker":"爱丽丝","text":"不过，这些对余来说完全无所谓。"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是圆环斗技场专卖的「能量爆发便当」有相当高的评价。"},{"kind":"dialogue","speaker":"鲁卡","text":"真是的，又是只关心食物……"},{"kind":"narration","speaker":"旁白","text":"随你便当怎么爆发，我感兴趣的是圆环斗技场。"},{"kind":"narration","speaker":"旁白","text":"那里一定有着来自世界各地的强力战士吧。"},{"kind":"narration","speaker":"旁白","text":"现在的我，到底实力如何呢？"},{"kind":"narration","speaker":"旁白","text":"有了希尔芙和诺姆的力量，我想应该没问题。"},{"kind":"narration","speaker":"旁白","text":"或许连取得优胜都不是美梦……"},{"kind":"dialogue","speaker":"鲁卡","text":"一定要去，优胜后有人找我要签名怎么办呢……"},{"kind":"dialogue","speaker":"鲁卡","text":"我也能成为一位名人啦！嘿嘿嘿嘿……"},{"kind":"dialogue","speaker":"爱丽丝","text":"白痴……！"},{"kind":"narration","speaker":"旁白","text":"白了我一眼，爱丽丝的目光回到了旅游指南上。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯嗯……遥远的东方边境之村——邪马台，有着独特的饮食文化。"},{"kind":"dialogue","speaker":"爱丽丝","text":"寿司、天妇罗、拉面、章鱼烧……"},{"kind":"dialogue","speaker":"爱丽丝","text":"哈，真是无比的期待……"},{"kind":"dialogue","speaker":"鲁卡","text":"东方边境的村子……？"},{"kind":"dialogue","speaker":"鲁卡","text":"还要绕道啊，不去，反正去那里也没有什么意义。"},{"kind":"narration","speaker":"旁白","text":"爱丽丝没说话，腮帮子鼓了起来。"},{"kind":"narration","speaker":"旁白","text":"然后尾巴朝我的脚缠了过来。"},{"kind":"dialogue","speaker":"鲁卡","text":"喂，住手啊，这是要干啥……"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的尾巴从我的脚缠至了腰上——"},{"kind":"dialogue","speaker":"鲁卡","text":"哎，我知道了，我知道啦…… 如果有空闲的时间就去啦！"},{"kind":"narration","speaker":"旁白","text":"要求得到满足，爱丽丝笑容满面。"},{"kind":"narration","speaker":"旁白","text":"……真是的，这个吃货。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……？什么声音？马蹄声？"},{"kind":"narration","speaker":"旁白","text":"不远处传来了马匹奔跑的声音。"},{"kind":"narration","speaker":"旁白","text":"经过了这么长时间，终于见到了其他的冒险者——"},{"kind":"dialogue","speaker":"鲁卡","text":"爱丽丝，赶紧变回人形！"},{"kind":"dialogue","speaker":"爱丽丝","text":"……没必要。"},{"kind":"dialogue","speaker":"爱丽丝","text":"只不过是一个正在发情的家伙……"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……？"},{"kind":"narration","speaker":"旁白","text":"说完莫名其妙的话语后，爱丽丝就不见了。"},{"kind":"narration","speaker":"旁白","text":"然后，马蹄声的来源出现在了我的面前——"},{"kind":"dialogue","speaker":"鲁卡","text":"啊…… 这次多亏了诺姆的力量啊。"},{"kind":"narration","speaker":"旁白","text":"出人意料的刚力从身体里涌出来了。"},{"kind":"narration","speaker":"旁白","text":"那个正是大地力量的本身。"},{"kind":"narration","speaker":"旁白","text":"没有那个力量的话，刚才被半人马娘按倒之时，就没法挣脱了吧——"},{"kind":"dialogue","speaker":"鲁卡","text":"用诺姆的力量，可以强行摆脱拘束啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"如果那个刚力能用在攻击上的话……"},{"kind":"dialogue","speaker":"爱丽丝","text":"现在的你是做不到的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"直接把刚力运用在剑上是很难打中敌人的。"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯……有道理，确实是那样。"},{"kind":"narration","speaker":"旁白","text":"第一次使用这个力量确实不习惯，很难控制。"},{"kind":"narration","speaker":"旁白","text":"刚才挣脱开拘束后，本以为可以继续用这个力量给予对方重创……"},{"kind":"narration","speaker":"旁白","text":"想要将刚力运用到剑上命中敌人的话，还得花费很长一段时间去习惯啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯，以后得加强修炼了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，尽量努力吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"对了，太阳差不多快下山了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"今晚就在这里野营吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……鲁卡，快去准备晚饭吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"哎呀……爱丽丝你脑袋里只有吃的啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"你有意见？"},{"kind":"narration","speaker":"旁白","text":"爱丽丝的眉毛突然上扬。"},{"kind":"dialogue","speaker":"爱丽丝","text":"弄得余好像一直在吃白食一样。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……那么，这次就由余来做饭。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊……！？ 爱丽丝，你会做饭……！？"},{"kind":"dialogue","speaker":"爱丽丝","text":"放马过来，没有魔王做不到的事！"},{"kind":"narration","speaker":"旁白","text":"完全不放心……"},{"kind":"narration","speaker":"旁白","text":"就这样，爱丽丝开始准备晚饭了。"},{"kind":"narration","speaker":"旁白","text":"总有一股不妙的感觉——"},{"kind":"dialogue","speaker":"鲁卡","text":"真的没问题吗，爱丽丝……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"当然，你以为余是谁。"},{"kind":"dialogue","speaker":"鲁卡","text":"真的真的真的没问题……？"},{"kind":"dialogue","speaker":"爱丽丝","text":"啊，啰嗦！"},{"kind":"dialogue","speaker":"爱丽丝","text":"在余把料理完成之前，你一边呆着去！"},{"kind":"narration","speaker":"旁白","text":"结果被赶出了料理制作的现场。"},{"kind":"narration","speaker":"旁白","text":"……不过，真的没问题吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"呼……看清余的实力吧！"},{"kind":"dialogue","speaker":"爱丽丝","text":"……成功击败了锅炉。"},{"kind":"dialogue","speaker":"鲁卡","text":"为什么你一脸得意的样子……"},{"kind":"narration","speaker":"旁白","text":"托你的福，今晚只能啃肉干了。"},{"kind":"narration","speaker":"旁白","text":"前略，天国的锅炉君，我会怀念你的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……这也是没办法的事啊，余从来没有受到过关于料理的教育。"},{"kind":"dialogue","speaker":"爱丽丝","text":"余学的是帝王学。料理什么的，那是新娘该学的东西。"},{"kind":"dialogue","speaker":"鲁卡","text":"帝王学……谁来教你这个？"},{"kind":"dialogue","speaker":"爱丽丝","text":"……玉藻。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那家伙，是本魔王的老师。"},{"kind":"dialogue","speaker":"鲁卡","text":"……这也就是说，爱丽丝其实比玉藻还年轻了？"},{"kind":"dialogue","speaker":"鲁卡","text":"话说爱丽丝的年龄有多大？"},{"kind":"dialogue","speaker":"鲁卡","text":"身为魔王的话，起码已经三百岁了吧？"},{"kind":"dialogue","speaker":"爱丽丝","text":"白痴！余今年２２！"},{"kind":"dialogue","speaker":"鲁卡","text":"哈！？这么年轻！？"},{"kind":"dialogue","speaker":"爱丽丝","text":"再年轻也比你大，好好尊敬我吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"这样的话……玉藻是爱丽丝的老师。"},{"kind":"dialogue","speaker":"鲁卡","text":"那么她到底是多少岁？"},{"kind":"dialogue","speaker":"爱丽丝","text":"……不知道。"},{"kind":"dialogue","speaker":"爱丽丝","text":"反正是四天王中年龄最大的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"她也是母亲大人的老师，不仅如此，传说她，"},{"kind":"dialogue","speaker":"爱丽丝","text":"已经连续担任了五代魔王的老师哟……"},{"kind":"narration","speaker":"旁白","text":"总觉得，听到了很可怕的信息。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……那么，讲故事时间到此为止。"},{"kind":"dialogue","speaker":"爱丽丝","text":"今晩继续进行战斗的训练。"},{"kind":"dialogue","speaker":"爱丽丝","text":"尽早掌握希尔芙和诺姆的力量。"},{"kind":"dialogue","speaker":"鲁卡","text":"好的，我会努力的！"},{"kind":"narration","speaker":"旁白","text":"于是，今晚也以爱丽丝为对手展开了训练。"},{"kind":"dialogue","speaker":"鲁卡","text":"哈啊，哈啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"还是老样子，没法充分发挥希尔芙的力量……"},{"kind":"dialogue","speaker":"爱丽丝","text":"之前就说过吧，将风寄宿在行动当中，使自己如疾风那样迅速。"},{"kind":"dialogue","speaker":"鲁卡","text":"是说过……"},{"kind":"narration","speaker":"旁白","text":"但是那太抽象了，实际做起来真的很困难。"},{"kind":"dialogue","speaker":"爱丽丝","text":"而且，你也该注意到了吧……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你没法同时使用希尔芙和诺姆的力量。"},{"kind":"dialogue","speaker":"爱丽丝","text":"使用风的力量，土之力量就消失了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"只能维持一个精灵，真是不成熟的家伙……"},{"kind":"dialogue","speaker":"鲁卡","text":"原来是这样吗…… 战斗中完全没注意到。"},{"kind":"narration","speaker":"旁白","text":"目前的自己，是没法同时呼出希尔芙和诺姆的。"},{"kind":"narration","speaker":"旁白","text":"也就是说，得根据敌人的情况判断应该召唤出哪只精灵。"},{"kind":"dialogue","speaker":"鲁卡","text":"等得到温蒂妮和萨莱曼达后，那会更复杂吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"切换着四种精灵，来应对战斗中不同的情况……"},{"kind":"dialogue","speaker":"爱丽丝","text":"有实力的人是可以同时召唤出多只精灵的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"寄风于行，寄土于身，寄水于心，寄火于技——"},{"kind":"dialogue","speaker":"爱丽丝","text":"做到这些的话，才能将精灵的真正力量充分发挥出来。"},{"kind":"dialogue","speaker":"鲁卡","text":"这个以前听你说过……总觉得，好玄妙啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"这些话，原本是谁说的？"}],"choices":[{"text":"继续","next":null}],"battles":["granberia-gate-vanguard"],"next":"F12"},"F12":{"id":"F12","title":"勇者神祠","status":"compiled","scenes":[{"kind":"dialogue","speaker":"鲁卡","text":"……好的，去戈德火山！"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，那么这个地区的事全都解决了？"},{"kind":"dialogue","speaker":"爱丽丝","text":"去了戈德火山不一定会回这里了。"},{"kind":"dialogue","speaker":"鲁卡","text":"好的，去戈德火山！"},{"kind":"narration","speaker":"旁白","text":"终于向戈德火山进发了。"},{"kind":"narration","speaker":"旁白","text":"在那里有着最后的精灵，萨莱曼达。"},{"kind":"narration","speaker":"旁白","text":"只要被她承认，我就能集全四精灵之力。"},{"kind":"narration","speaker":"旁白","text":"那么，那到底是什么样的力量呢——"},{"kind":"narration","speaker":"旁白","text":"今天照样野营。"},{"kind":"narration","speaker":"旁白","text":"这几天都在进行水之力和内心的训练。"},{"kind":"narration","speaker":"旁白","text":"虽然有了点感觉——"},{"kind":"narration","speaker":"旁白","text":"但是依然没有任何实质性进展。"},{"kind":"narration","speaker":"旁白","text":"这个特训真的适合我吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"来吧，像平常一样闭上眼睛坐禅。"},{"kind":"dialogue","speaker":"爱丽丝","text":"要好好地躲过余的攻击哦。"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯……这样真的能变强吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"总觉得这个精神锻炼不太行啊……"},{"kind":"dialogue","speaker":"爱丽丝","text":"你是在怀疑这个修习吗？"},{"kind":"dialogue","speaker":"爱丽丝","text":"连海因里希的教导都怀疑，你想成为真正的勇者吗？"},{"kind":"dialogue","speaker":"鲁卡","text":"好吧，就这么做吧……！"},{"kind":"narration","speaker":"旁白","text":"总觉得我又像往常一样被骗了——"},{"kind":"narration","speaker":"旁白","text":"于是我静静地闭着眼睛。"},{"kind":"dialogue","speaker":"鲁卡","text":"嗯！"},{"kind":"dialogue","speaker":"鲁卡","text":"切！"},{"kind":"dialogue","speaker":"鲁卡","text":"喝！"},{"kind":"dialogue","speaker":"鲁卡","text":"怒～～～～！"},{"kind":"dialogue","speaker":"爱丽丝","text":"哼，嘴里在咕噜什么呢……"},{"kind":"dialogue","speaker":"鲁卡","text":"总觉得最后燃尽了啊……"},{"kind":"narration","speaker":"旁白","text":"先不说这个，修炼花费了巨大的精神力。"},{"kind":"narration","speaker":"旁白","text":"再继续的话，就真的燃干净了。"},{"kind":"dialogue","speaker":"鲁卡","text":"那个，爱丽丝。"},{"kind":"dialogue","speaker":"鲁卡","text":"差不多该教我新技能了吧……"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯……你也能够较好地使用土之力了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"那么就教你使用大地之力的剑术吧。"},{"kind":"dialogue","speaker":"鲁卡","text":"太棒了！"},{"kind":"narration","speaker":"旁白","text":"接着，我开开心心地接受了爱丽丝的教导——"},{"kind":"dialogue","speaker":"鲁卡","text":"这样…… 哈！/"},{"kind":"narration","speaker":"旁白","text":"经过指导，要领是掌握住了。"},{"kind":"narration","speaker":"旁白","text":"将大地之力充满全身，用力地扣下——"},{"kind":"narration","speaker":"旁白","text":"这就是附加土之力量的天魔头盖斩。"},{"kind":"dialogue","speaker":"爱丽丝","text":"嗯，理解了就好。"},{"kind":"dialogue","speaker":"爱丽丝","text":"这个技能是天魔头盖斩的派生技能。"},{"kind":"dialogue","speaker":"爱丽丝","text":"运用土之力量起跳再扣下——"},{"kind":"dialogue","speaker":"爱丽丝","text":"这就是，坏斧·大山鸣动。"},{"kind":"dialogue","speaker":"鲁卡","text":"坏斧…… 这是斧技能？"},{"kind":"dialogue","speaker":"爱丽丝","text":"创造这个技能的米诺陶洛斯娘是使用斧头的。"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是就算是用剑释放也没有关系。"},{"kind":"dialogue","speaker":"爱丽丝","text":"传说中的魔斧战士米诺陶，使用这个技能劈开了一座山。"},{"kind":"dialogue","speaker":"鲁卡","text":"果然又是魔物的技能呢。"},{"kind":"dialogue","speaker":"鲁卡","text":"不过好歹没去劈人。"},{"kind":"narration","speaker":"旁白","text":"按照惯例的话，肯定又伴随着一堆血腥的传说——"},{"kind":"dialogue","speaker":"爱丽丝","text":"你在说什么呢，白痴。"},{"kind":"dialogue","speaker":"爱丽丝","text":"山上住的人类也全部变成碎片了。"},{"kind":"dialogue","speaker":"鲁卡","text":"……呜呜……"},{"kind":"narration","speaker":"旁白","text":"果然又是这种令人不愉快的技能。"},{"kind":"narration","speaker":"旁白","text":"不过话说回来，终于又学会强大的一招了！"},{"kind":"narration","speaker":"旁白","text":"「坏斧·大山鸣动」学成！"},{"kind":"dialogue","speaker":"爱丽丝","text":"技能的基本特征和天魔头盖斩相似。"},{"kind":"dialogue","speaker":"爱丽丝","text":"不过，现在可以不依靠高地便能释放了。"},{"kind":"dialogue","speaker":"鲁卡","text":"那还真是方便。"},{"kind":"narration","speaker":"旁白","text":"天魔头盖斩受地形限制，有时不能用。"},{"kind":"narration","speaker":"旁白","text":"不过坏斧·大山鸣动就不需要担心这种事了。"},{"kind":"dialogue","speaker":"爱丽丝","text":"另外，如果在诺姆存在的状态下使用这一招，威力会增加。"},{"kind":"dialogue","speaker":"爱丽丝","text":"……嗯，已经掌握了这么多魔剑术了啊。"},{"kind":"dialogue","speaker":"爱丽丝","text":"现在你也是一位非常出色的魔剑士了。"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，谢谢——"},{"kind":"dialogue","speaker":"鲁卡","text":"——等一下，魔剑士！？"},{"kind":"narration","speaker":"旁白","text":"确实，我的魔族技能都能摆一排了！"},{"kind":"narration","speaker":"旁白","text":"但是我的目标可是勇者啊！"},{"kind":"dialogue","speaker":"爱丽丝","text":"和冒牌勇者相比，还是魔剑士更加好吧。"},{"kind":"dialogue","speaker":"爱丽丝","text":"干脆你就转职成魔剑士算了？"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，伊莉娅丝大人请原谅我……"},{"kind":"narration","speaker":"旁白","text":"我仰望天空，向伊莉娅丝大人请求原谅——"},{"kind":"dialogue","speaker":"鲁卡","text":"啊，好热……"},{"kind":"narration","speaker":"旁白","text":"热热热热热。"},{"kind":"narration","speaker":"旁白","text":"踏入戈德火山洞窟的一瞬间，我就差点被烤熟了。"},{"kind":"narration","speaker":"旁白","text":"但是和那灼热的空气相反的是静谧的氛围。"},{"kind":"narration","speaker":"旁白","text":"这和以前精灵所在地的氛围很相似。"},{"kind":"dialogue","speaker":"鲁卡","text":"这火山，有着萨莱曼达……"},{"kind":"dialogue","speaker":"爱丽丝","text":"萨莱曼达作为妖魔中的猛者而出名。"},{"kind":"dialogue","speaker":"爱丽丝","text":"所以住在这里基本是总所周知的事。"},{"kind":"dialogue","speaker":"爱丽丝","text":"想当萨莱曼达徒弟的魔剑士也很多。"},{"kind":"dialogue","speaker":"爱丽丝","text":"但是全都吃了闭门羹。"},{"kind":"dialogue","speaker":"鲁卡","text":"猛者……"},{"kind":"narration","speaker":"旁白","text":"难道说，要想获得力量必须先打倒我之类的。"},{"kind":"narration","speaker":"旁白","text":"如果对手是个凶猛的家伙，肯定免不了一场恶战啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"不……再这样下去，见到萨莱曼达之前我就会被烤熟了。"},{"kind":"dialogue","speaker":"鲁卡","text":"快点走吧——"},{"kind":"dialogue","speaker":"希尔芙","text":"萨莱曼达的气味哟～☆"},{"kind":"narration","speaker":"旁白","text":"我的心中形成了两人的身影。"},{"kind":"dialogue","speaker":"鲁卡","text":"你知道在哪吗？"},{"kind":"dialogue","speaker":"希尔芙","text":"就在里面……直走就是！"},{"kind":"dialogue","speaker":"鲁卡","text":"原来如此，谢啦。"},{"kind":"dialogue","speaker":"鲁卡","text":"话说，温蒂妮呢？"},{"kind":"dialogue","speaker":"希尔芙","text":"已经热得融化了！"},{"kind":"narration","speaker":"旁白","text":"喂喂。"},{"kind":"narration","speaker":"旁白","text":"竟然融化了……"},{"kind":"dialogue","speaker":"希尔芙","text":"诺姆酱也热得毫无精神啊。"},{"kind":"dialogue","speaker":"希尔芙","text":"哈哈哈☆"},{"kind":"narration","speaker":"旁白","text":"希尔芙精神倒是很好啊。"},{"kind":"narration","speaker":"旁白","text":"好吧，只要直走就行了吧——"},{"kind":"dialogue","speaker":"鲁卡","text":"好的，走了……！"},{"kind":"narration","speaker":"旁白","text":"我和爱丽丝在灼热中前进——"},{"kind":"dialogue","speaker":"鲁卡","text":"剩下的得想办法收集情报——"},{"kind":"dialogue","speaker":"？？？","text":"有人在呼唤我……！？"},{"kind":"dialogue","speaker":"鲁卡","text":"你，你是——！"},{"kind":"narration","speaker":"旁白","text":"谜之垃圾箱出现！/"},{"kind":"dialogue","speaker":"鲁卡","text":"……谁啊？"},{"kind":"dialogue","speaker":"亚米拉","text":"是我啊，亲爱的。"},{"kind":"narration","speaker":"旁白","text":"垃圾箱里的亚米拉探出了头！"},{"kind":"dialogue","speaker":"鲁卡","text":"……你躲在这里干什么？"},{"kind":"dialogue","speaker":"亚米拉","text":"这个地方是伊莉娅丝逆十字的根据地的吧？"},{"kind":"dialogue","speaker":"亚米拉","text":"不能让他们找到，所以我躲起来了。"},{"kind":"dialogue","speaker":"鲁卡","text":"一直躲在垃圾桶里吗……"},{"kind":"dialogue","speaker":"亚米拉","text":"虽然躲进了垃圾桶了，但是我出不来……"},{"kind":"dialogue","speaker":"亚米拉","text":"好吧，我告诉你我收集到的宝玉情报。"},{"kind":"narration","speaker":"旁白","text":"话说——在格兰戈德时，爱丽丝就委托了亚米拉去调查了宝玉。"},{"kind":"narration","speaker":"旁白","text":"那个时候就预料到了这个情况啊。"},{"kind":"narration","speaker":"旁白","text":"不得不向想得如此周到的爱丽丝道谢啊。"},{"kind":"dialogue","speaker":"鲁卡","text":"那就拜托了。"}],"choices":[{"text":"继续","next":null}],"battles":["carmilla-noble-banquet-invitation","queen-vampire-court-investiture"],"next":null},"M01":{"id":"M01","title":"渡海准备","status":"pending","scenes":[],"battles":[]},"M02":{"id":"M02","title":"莱米纳废墟","status":"pending","scenes":[],"battles":[]},"M03":{"id":"M03","title":"大陆行军","status":"pending","scenes":[],"battles":[]},"M04":{"id":"M04","title":"魔王城封锁","status":"pending","scenes":[],"battles":[]},"M05":{"id":"M05","title":"阿露艾露玛决战","status":"pending","scenes":[],"battles":[]},"M06":{"id":"M06","title":"玉藻决战","status":"pending","scenes":[],"battles":[]},"M07":{"id":"M07","title":"艾露贝提耶决战","status":"pending","scenes":[],"battles":[]},"M08":{"id":"M08","title":"古兰贝莉娅决战","status":"pending","scenes":[],"battles":[]},"M09":{"id":"M09","title":"魔王真相","status":"pending","scenes":[],"battles":[]},"M10":{"id":"M10","title":"伊莉娅丝降临","status":"pending","scenes":[],"battles":[]},"X02":{"id":"X02","title":"共存之路","status":"pending","scenes":[],"battles":[]},"T01":{"id":"T01","title":"天使军侵攻","status":"pending","scenes":[],"battles":[]},"T02":{"id":"T02","title":"爱丽丝封印","status":"pending","scenes":[],"battles":[]},"T03":{"id":"T03","title":"四精灵离散","status":"pending","scenes":[],"battles":[]},"T04":{"id":"T04","title":"血统真相","status":"pending","scenes":[],"battles":[]},"T05":{"id":"T05","title":"米卡艾拉","status":"pending","scenes":[],"battles":[]},"T06":{"id":"T06","title":"地上联合","status":"pending","scenes":[],"battles":[]},"T07":{"id":"T07","title":"解救爱丽丝","status":"pending","scenes":[],"battles":[]},"T08":{"id":"T08","title":"反攻天界","status":"pending","scenes":[],"battles":[]},"T09":{"id":"T09","title":"普罗米斯汀","status":"pending","scenes":[],"battles":[]},"T10":{"id":"T10","title":"黑之爱丽丝","status":"pending","scenes":[],"battles":[]},"T11":{"id":"T11","title":"爱丽丝十五世真相","status":"pending","scenes":[],"battles":[]},"T12":{"id":"T12","title":"伊莉娅丝最终局","status":"pending","scenes":[],"battles":[]},"T13":{"id":"T13","title":"战后结算","status":"pending","scenes":[],"battles":[]},"FR01":{"id":"FR01","title":"流浪者之路","status":"pending","scenes":[],"battles":[]},"FR02":{"id":"FR02","title":"世界时钟推进","status":"pending","scenes":[],"battles":[]},"FR03":{"id":"FR03","title":"旧地重游","status":"pending","scenes":[],"battles":[]},"FR04":{"id":"FR04","title":"新秩序建立","status":"pending","scenes":[],"battles":[]}}}')}}]);